window.HYMNS=(window.HYMNS||[]).concat([{"id": "pp001", "cat": "pp", "title": "ابنك مشغول بذاته", "text": "1- ابنك مشغول بذاته احميني\nابنك مشغول بالعالم\nنجيني\n\nق) ياللي انت جاي\nقريب جاي\nعقلني سيدي\nوصحيني\n\n2- ابنك غلبته لذاته احميني\nمأسور من شهواته\nنجيني\n\nق) ياللي انت جاي\nقريب جاي\nعقلني سيدي\nوصحيني\n\n3- ابنك مشغول عنك\nاحميني\nوعنده اغلى منك\nنجيني\n\nق) ياللي انت جاي\nقريب جاي\nعقلني سيدي\nوصحيني\n\n4- ابنك باين غروره\nاحميني\nولا تاب عن كل شروره\nنجيني\n\nق) ياللي انت جاي\nقريب جاي\nعقلني سيدي\nوصحيني\n\n5- ابنك بيبص لغيره\nاحميني\nوناسي سيرته وسيره\nنجيني\n\nق) ياللي انت جاي\nقريب جاي\nعقلني سيدي\nوصحيني\n\n6- ابنك محبته باردة\nاحميني\nوافكاره في الدنيا شاردة\nنجيني\n\nق) ياللي انت جاي\nقريب جاي\nعقلني سيدي\nوصحيني\n\n7- ابنك مشغول فاضي\nاحميني\nوقبل ما تبقى قاضي\nنجيني\n\nق) ياللي انت جاي\nقريب جاي\nعقلني سيدي\nوصحيني"}, {"id": "pp002", "cat": "pp", "title": "اتبناني", "text": "ق) اتبناني\nورضي بيَّ\nاشتراني\nوحنّ عليَّ\n\n1- ابن وليَّ شأن كبير\nابويا يبقى القدير\nوازاي اخاف انا م الشرير\nمهما جاني\n\nق) اتبناني\nورضي بيَّ\nاشتراني\nوحنّ عليَّ\n\n2- بقى لي في حضنه مكان\nونسيت ايام الحرمان\nده اهلي وعيلتي كمان\nوراس مالي\n\nق) اتبناني\nورضي بيَّ\nاشتراني\nوحنّ عليَّ\n\n3- تعالوا شوفوا يا ناس\nيسوع اداني الخلاص\nماشي معاه مرفوع الراس\nعلَّى مقامي\n\nق) اتبناني\nورضي بيَّ\nاشتراني\nوحنّ عليَّ\n\n4- نساني الماضي القديم\nخلى لساني يقول ترانيم\nغسلني بدمه الكريم\nوفداني\n\nق) اتبناني\nورضي بيَّ\nاشتراني\nوحنّ عليَّ\n\n5- اعيش لك طول السنين\nعبد خاضع وامين\nولا احيد عنه شمال ويمين\nطول ايامي\n\nق) اتبناني\nورضي بيَّ\nاشتراني\nوحنّ عليَّ"}, {"id": "pp003", "cat": "pp", "title": "احبني ربي", "text": "1- يا عجباً مخلصي\nقد مات من أجلي\nوسُفِكَ الدم الذكي\nلخاطئ مثلي\n\nق) احبني ربي\nنعم احبني\nيسوع قد احبني\nلذا مات عني\n\n2- لمَّا الشمس قد اظلمت\nمن غير عادة\nحُزناً على من مات\nكي يمحوا خطيتي\n\nق) احبني ربي\nنعم احبني\nيسوع قد احبني\nلذا مات عني\n\n3- يا قوم ماذا اهدي\nمن قد فاق حبه\nنفسي لك وهذا\nما استطعت فعله\n\nق) احبني ربي\nنعم احبني\nيسوع قد احبني\nلذا مات عني\n\n4- هل حبي لك كي\nاوفي هذا الحب العجيب\nحبي لك إزاء حبك\nلا شئ يا حبيب\n\nق) احبني ربي\nنعم احبني\nيسوع قد احبني\nلذا مات عني\n\n5- يا رب هب لي\nأن ارى يسوع والصليب\nكي ما تفيض ادمعي\nبالحمد للحبيب\n\nق) احبني ربي\nنعم احبني\nيسوع قد احبني\nلذا مات عني"}, {"id": "pp004", "cat": "pp", "title": "احلى حبيب بيعزني", "text": "1- احلى حبيب بيعزيني\nمن طيبة قلبه يسبيني\nويسهل كل الصعاب\nوبنور حبه هداني\n\nق) يسوع مش حد تاني\nيسوع اللي نجاني\nانقذ نفسي من العذاب\nوبنور حبه هداني\n\n2- نساني كل الشرور\nوقلبي ملاه بالنور\nوفتح قدامي الباب\nوبنور حبه هداني\n\nق) يسوع مش حد تاني\nيسوع اللي نجاني\nانقذ نفسي من العذاب\nوبنور حبه هداني\n\n3- خلاني دايماً فرحان\nواشوف جماله بالإيمان\nمن حنانه القلب ذاب\nوبنور حبه هداني\n\nق) يسوع مش حد تاني\nيسوع اللي نجاني\nانقذ نفسي من العذاب\nوبنور حبه هداني\n\n4- نفسي اقول لكل الناس\nليسوع وحده الخلاص\nمفيش غيره هو الباب\nوبنور حبه هداني\n\nق) يسوع مش حد تاني\nيسوع اللي نجاني\nانقذ نفسي من العذاب\nوبنور حبه هداني"}, {"id": "pp005", "cat": "pp", "title": "احنا معاك", "text": "1- احنا معاك\nيا يسوع\nاحنا معاك\nبلا رجوع\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n2- احنا معاك\nمهما يكون\nفي امراض\nوفي سجون\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n3- انت إلهنا\nواحنا اولادك\nاوهبنا\nحفظ كلامك\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n4- جيت على الارض\nكإنسان\nونشرت بينا\nالسلام\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n5- مشيت في الحر\nستة ساعات\nلتربح نفس\n للإيمان\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n6- حُبك لأولادك\nبان\nمنذ تأسيس\nالعالم\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n7- اتحملت\nعلشانا كتير\nسب ولطم\nوإهانات\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n8- صلبوك\nبين لصين\nحكموا عليك\nكالمجرمين\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n9- سُفِك دماك\nفوق الصليب\nعلامة حب\nوخلاص اكيد\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n10- بالتهليل\nوالتسبيح\nبالصلوات\nنصرخ ونصيح\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n11- قولوا معانا\nعاهدناك\nنسلك حسب\nوصاياك\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك\n\n12- بالتعليم\nالارثوذكسي\nوالتقليد \nالرسولي\n\nق) رغم الحرب\nورغم الضيق\nهنا الكل\nثابت فيك"}, {"id": "pp006", "cat": "pp", "title": "ادعو الإله", "text": "1- أدعو الإله ، وقت الصلاة يعطي حياة ، فيها نجاة      فيها الهُدا ، للخاطئين ، للآثمين ، للمذنبين ، للجاحدين ، \n(منهم أنا ) 2\n\n2- أدعو الرؤوف ، ربي العطوف، ينسى القصاص ، يعطي الخلاص ، يعطي الرجاء ، للتائبين ، للنادمين ، للصابرين ، للذاهدين ، \n(منهم أنا) 2\n\n3- ادعو المسيح ، كي ما يريح ، في الضائقات ، في النازلات ،\n وفي العناء ، الكادحين ، والرازحين ، والمتعبين ، والمجهدين ، (منهم أنا) 2\n\n4- ادعو الحبيب ، ربي المُجيب ، يهب الحنان ، يهب الامان ،    يهب الحما ، للخائفين ،   للجازعين ، للخائرين ،\n (منهم أنا) 2\n\n5- ادعو القدير ، ربي النصير ، عند الهموم ، كي لا تدوم ،   يعطي العزاء ، للبائسين ، لليائسين ، للصارخين ، متوجعين (منهم أنا) 2\n\n6- ادعو الكريم ، ربي الرحيم ، يهب السلام ، يعطي الطعام ، يهدي المنا ، للطالبين ، للمعوزين ، للجائعين ، للظمأنين \n(منهم أنا) 2\n\n7- ادعو المعين ، ربي الأمين ، يعطي الصلاح ، يعطي الفلاح ، يعطي الهنا ، للمؤمنين ، للصالحين ، للمتقين ، للعابدين ، \n(ياليتني منهم أنا) 2 "}, {"id": "pp007", "cat": "pp", "title": "ارجوك يا رب", "text": "ق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n1- جيتلك مريض\n مانفعش طبيب\nألمسني بأيدك \nيا اقوى طبيب\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n2- جيتلك محتاج\nيا ابو الايتام\nاشبعني بيك\nكل الايتام\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n3- جيتلك مهموم\nوانا كُلي ذنوب\nاديني نعمة\nعلمني اتوب\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n4- جيتلك حزين\nكئيب وذليل\nبنعمة غنية\nخلتني سعيد\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n5- جيتلك مطرود\nيائس وجريح\nده انت ابويا\nسندي الوحيد\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n6- جيتلك مظلوم\n من كل الناس\nوعشمي فيك\nتنصفني يا بار\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n7- جيتلك وماليش\nصدر حنون\nواثق يا ابويا\nعلى العز هادوس\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n8- جيتلك تعبان\nخايف مُهان\nشارتني بدمك\nاعطيتني سلام\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n9- جيتلك حيران\nمغلوب لزمان\nوبقوة منك\nادوس الشيطان\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي\n\n10- جيتلك بإيمان\nفي وعود زمان\nهانكون وياك\nفوق في السماء\n\nق) ارجوك يا ربي\nتدبر امري\nبشفاعة العدرا\nتغفرلي ذنبي"}, {"id": "pp008", "cat": "pp", "title": "اسمعوا يا مؤمنين", "text": "1- اسمعوا يا مؤمنين\nوتعالوا يا خاطئين\nبتوبة فرحين\n\nق) ده وعدنا نعيش وياه\n\nنتمتع معاه في سماه\n\n2- نبقى في السماء امين\nحُضَّار مع غائبين\nونعاشر القديسين\n\nق) ده وعدنا نعيش وياه\n\nنتمتع معاه في سماه\n\n3- هناك ملاك جليل\nاسمه ميخائيل\nرئيس الجند عظيم\n\nق) ده وعدنا نعيش وياه\n\nنتمتع معاه في سماه\n\n4- نلاقى انبا انطونيوس\nوحبيبنا البابا كيرلس\nيصلوا ويشفعوا فينا\n\nق) ده وعدنا نعيش وياه\n\nنتمتع معاه في سماه\n\n5- ونشوف امنا دميانة\nواربعين عذراء وياها\nقائلين سبحوا معانا\n\nق) ده وعدنا نعيش وياه\n\nنتمتع معاه في سماه\n\n6- وبخور حوالينا جميل\nنلبس تيجان واكاليل\nبالفرح مرنمين\n\nق) ده وعدنا نعيش وياه\n\nنتمتع معاه في سماه\n\n7- الشهداء الابرار\nاعترفوا بإفتخار\nودمائهم بقيت انهار\n\nق) ده وعدنا نعيش وياه\n\nنتمتع معاه في سماه\n\n8- كنيستنا اليوم فرحانة\nبصلاة مع صوم سهرانة\nنبقى في السماء جواها\n\nق) ده وعدنا نعيش وياه\n\nنتمتع معاه في سماه"}, {"id": "pp009", "cat": "pp", "title": "اسمك معطر يا امي", "text": "1- شفيعة عظيمة في كل ضيقة\nمع بربارة ويوليانة\nوالأم رفقة وهيلانة\nوسوسنة ودميانة\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون\n\n2- صديقة قوية معينة سريعة\nلكل اولادك في السموات\nنصلي دائماً للرب تملي\nيرفع ويزيل كل الاتعاب\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون\n\n3- محبة فريدة للأمهات\nخدمتي في حياتك بكل اتضاع\nبصوم وصلاة عيشتي لربك\nفي انكار ذات طول الحياة\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون\n\n4- من كل بلد جايين اولادك\nطالبين شفاعتك امام الله\nأضاءوا الشموع قدام صورتك\nصارخين ليسوع طالبين النجاة\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون\n\n5- صرتي منارة يا امي ايريني\nلكل جيل من الاجيال\nاشفعي يا امي وصلي عني\nعند يسوع رب القوات\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون\n\n6- البابا كيرلس رجل الصلاة\nتنبأ ليكي امي يا تماف\nهاتكوني عظيمة وكمان رئيسة\nلدير حبيبك ابو سيفين\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون\n\n7- لكل بناتك كنتي رسالة\nوصورة حية في الجهاد\nيا قدوة لينا اشفعي فينا\nامام يسوع رب القوات\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون\n\n8- نرجو يا امي تصلي تملي\nلكل مريض حزين تعبان\nوللمساجين انتي معين\nمع ابو سيفين امام الله\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون\n\n9- رسالة جميلة لكل يآئس\nمغلوب من ابليس الشرير\nوريحة زكية ليسوع فادينا\nلكل خاطي تايه في الحياة\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون\n\n10- يا ام حنون لكل عليل\nوبلسم يداوي كل الجروح\nوام معينة لكل ذليل\nشفاعة لأجله امام المسيح\n\nق) ده اسمك معطر مسكر يا امي\nايريني حبيبة المسيح\nوامك العذراء بقت ليكي ملجأ\nفي وسط الآلام ليكي ام حنون"}, {"id": "pp010", "cat": "pp", "title": "اسم معناه جميل", "text": "1- اسمك معناه جميل\nعذراء مالكيش مثيل\nسيدة السمائيين\nوكمان الارضيين\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين\n\n2- انتي الحصن الحصين\nوالملجأ للجميع\nشيلتي يسوع طفل رضيع\nشيلتيه كالبشريين\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين\n\n3- حبي يا عدرا انا\nيوم بعد يوم نما\nليكي يا باب السما\nيا فرحة كل حزين\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين\n\n4- يا تابوت العهد انتي\nيا عدرا حملتي\nرب المجد شيلتي\nالجالس على الشاروبيم\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين\n\n5- يا عصا هارون محتاج\nدي شفاعتك شفاء وعلاج\nولدتي بدون زواج\nرب الناس اجمعين\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين\n\n6- يا منارة ذهبية\nيا ذات البتولية\nمريم اشفعي فيَّ\nيا رجاء المسيحيين\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين\n\n7- مريم يا تي بارثينوس\nيا سماء تانية لأيسوس\nسكن فيكي بي اجيوس\nالواحد من اتنين\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين\n\n8- يا والدة الإله\nضعفي ما انتي عارفاه\nعجزنا انتي حاسباه\nصلي عنا كل حين\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين\n\n9- يا زهرة منيرة\nوغير متغيره\nيا شجرة مثمرة\nشفاعتك كل حين\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين\n\n10- صلواتك لينا بخور\nامام خالق الدهور\nصلي لي يا ام النور\nيا شفيعة في المؤمنين\n\nق) يا عذراء دي شفاعتك\nنجاه للغرقانين\nيا مريم بصلاتك\nتهدي التائبين"}, {"id": "pp011", "cat": "pp", "title": "اشتقت لبيتك", "text": "ق) اشتقت لبيتك يا ربي\nوكأني غبت بقالي زمان\nاشتقت لكل حاجة فيه\nارضه وبيبانه والحيطان\n\n1- اشتقت لرنة اجراسه\nوالشعب متهلل فرحان\nاشتقت اني اقوم بدري\nواروحله حتى ولو تعبان\n\nق) اشتقت لبيتك يا ربي\nوكأني غبت بقالي زمان\nاشتقت لكل حاجة فيه\nارضه وبيبانه والحيطان\n\n2- اشتقت لصوت الشمامسة\nوصلاة عشية والألحان\nرفع بخور والقداسات\nالراحة فيه والأمان\n\nق) اشتقت لبيتك يا ربي\nوكأني غبت بقالي زمان\nاشتقت لكل حاجة فيه\nارضه وبيبانه والحيطان\n\n3- من كل قلبي يا رب بتوب\nوعلى خطايايا انا ندمان\nكم مرة كان قدامي اروح\nوكنت عن بيتك غفلان\n\nق) اشتقت لبيتك يا ربي\nوكأني غبت بقالي زمان\nاشتقت لكل حاجة فيه\nارضه وبيبانه والحيطان\n\n4- اغفر خطايانا وآثامنا\nاطرحها في بحر النسيان\nده ليس عبد بلا خطية\nولا سيد بلا غفران\n\nق) اشتقت لبيتك يا ربي\nوكأني غبت بقالي زمان\nاشتقت لكل حاجة فيه\nارضه وبيبانه والحيطان\n\n5- اجعل ابواب الكنائس\nمفتوحة على مر الزمان\nده بيتك هو يا رب الفُلك\nاللي ينجينا من الطوفان\n\nق) اشتقت لبيتك يا ربي\nوكأني غبت بقالي زمان\nاشتقت لكل حاجة فيه\nارضه وبيبانه والحيطان"}, {"id": "pp012", "cat": "pp", "title": "اشكر يسوع", "text": "ق) أشكر يسوع اللي فداني\nوبصلبه وموته احياني\nمات عني البار. وفدى الأشرار\nوبدمه الغالي حررني\n\n1- انا كنت هالك بذنوبي\nواعمى لا اعرف طريقي\nوجاني يسوع ومسح لي الدموع\nولا عاد يذكر اثامي تاني\n\nق) أشكر يسوع اللي فداني\nوبصلبه وموته احياني\nمات عني البار. وفدى الأشرار\nوبدمه الغالي حررني\n\n2- مديون اشهدلك يا فاديَّ\nمن أجل خلاصك ليَّ\nاحببتني خلصتني\nواعطيتني حياة ابدية\n\nق) أشكر يسوع اللي فداني\nوبصلبه وموته احياني\nمات عني البار. وفدى الأشرار\nوبدمه الغالي حررني"}, {"id": "pp013", "cat": "pp", "title": "اشكرك على ظروفي", "text": "1- أشكرك على ظروفي\nدي وعودك بتنسيني خوفي\nوبتطمني على اللي آتي\nيا رب ضامن فيك حياتي\n\nق) ومسلم ليك امري\nانت حافظ عمري\nيا سندي ويا ستري\nيا مكفيني بخيرك\nوحدك ماليش غيرك\nوبحكمة تدبيرك\nتفاصيل مواعيدي\n\n2- ومين يقول بعد كلامك\nيا مالي ايامك بسلامك\nياللي ايدك فوق الايادي\nكل اتكالي عليك يا فادي\n\nق) ومسلم ليك امري\nانت حافظ عمري\nيا سندي ويا ستري\nيا مكفيني بخيرك\nوحدك ماليش غيرك\nوبحكمة تدبيرك\nتفاصيل مواعيدي\n\n3- لحظة ما بقول أعني\nحمل ثقيل يتشال عني\nواتذكر يا رب صلاحك\nتتبدل احزاني بأفراحك\n\nق) ومسلم ليك امري\nانت حافظ عمري\nيا سندي ويا ستري\nيا مكفيني بخيرك\nوحدك ماليش غيرك\nوبحكمة تدبيرك\nتفاصيل مواعيدي"}, {"id": "pp014", "cat": "pp", "title": "اصليله", "text": "1- اصليله \nتحير عقلي تدابيره\nبيقفل باب \nويفتح الف باب غيره\n\nيدوب يلمح ايديا امامه مرفوعة\nبحب عجيب عليَّ يفيض جزيل خيره\n\nمبفهمهوش \nساعات يمكن وبتذمر\nواشوفه بعيد\nفي وقت الضيق ومتأخر\n\nيقول اصبر \nمتستعجلش على فرحك\nانا بإيدي بجهزلك\nفرح اكبر\n\nق) بيبعت \nرحمة للسهران في ليل قاسي\nويبعت\nنعمة للغلان وللناسي\n\nوبيطبطب \nعلى المهموم وبيواسي\nويفتح\nطاقة للمسجون في احزانه\n\nحنين\nواللي داق منه اكيد عارفه\nيحوط\nع اللي ماشي في سكته وشايفه\n\nويصبر\nع اللي ماشي بعيد وبيخالفه\nويوفي العهد\nلو كل البشر خانوا\n\n2- اروح عنده\nاحط الحمل واسيبه\nوانام مرتاح\nما انا واثق في ترتيبه\n\nولا يشغلني خوف\nمن جاي وليه وازاي\nبقول الخير\nيا رب انت اللي هاتجيبه\n\nسخية ايديه\nوجوه عينيه انا متشال\nوفي حضوره\nبحس بكل راحة بال\n\nده قال في وعوده\nهيعوضني عن اتعاب\nسنين عدت\nوبكرة هيبقى احسن حال\n\nق) بيبعت \nرحمة للسهران في ليل قاسي\nويبعت\nنعمة للغلان وللناسي\n\nوبيطبطب \nعلى المهموم وبيواسي\nويفتح\nطاقة للمسجون في احزانه\n\nحنين\nواللي داق منه اكيد عارفه\nيحوط\nع اللي ماشي في سكته وشايفه\n\nويصبر\nع اللي ماشي بعيد وبيخالفه\nويوفي العهد\nلو كل البشر خانوا"}, {"id": "pp015", "cat": "pp", "title": "اعلن ذاتك ومجدك", "text": "ق) اعلن ذاتك ومجدك \nوتمم لينا وعدك\nونشوفك في وسطينا\nوتدوقنا من شهدك\n\n1- هللي يا نفسي وغني\nوعد حبيبي بيطمني\nهو معايا وانا معاه\nوشايل همي عني\n\nق) اعلن ذاتك ومجدك \nوتمم لينا وعدك\nونشوفك في وسطينا\nوتدوقنا من شهدك\n\n2- حضورك سر فرحنا\nعازنا وانشرحنا\nيا مظلل بالحب علينا\nانت لينا واحنا ليك\n\nق) اعلن ذاتك ومجدك \nوتمم لينا وعدك\nونشوفك في وسطينا\nوتدوقنا من شهدك\n\n3- مد يدك للشفاء\nواجري يا يسوع آيات\nواعطي لأسمك مجداً\nواصنع بينا معجزات\n\nق) اعلن ذاتك ومجدك \nوتمم لينا وعدك\nونشوفك في وسطينا\nوتدوقنا من شهدك"}, {"id": "pp016", "cat": "pp", "title": "الأبرع جمالاً", "text": "1- الأبرع جمالاً \nمن بني البشر\nهو بينجينا \nمن كل خطر \nما أجملك ما أجملك\n\nق) كل يوم كنت جنبي\nالطبيب المقيم\nولا يوم غبت عني\nالصديق الحميم \nما أجملك ما أجملك\n\n2- ليس مثلك \nيا ملكنا\nتركب السحاب\nلمعونتنا\nما اجملك ما اجملك\n\nق) كل يوم كنت جنبي\nالطبيب المقيم\nولا يوم غبت عني\nالصديق الحميم \nما أجملك ما أجملك\n\n3- يوم دعوتك\nاحببتني\nقوة في نفسي\nشجعتني\nما اجملك ما اجملك\n\nق) كل يوم كنت جنبي\nالطبيب المقيم\nولا يوم غبت عني\nالصديق الحميم \nما أجملك ما أجملك\n\n4- على الأذرع الأبدية\nحملتني\nولحضنك الدافي\nضممتني\nما اجملك ما اجملك\n\nق) كل يوم كنت جنبي\nالطبيب المقيم\nولا يوم غبت عني\nالصديق الحميم \nما أجملك ما أجملك"}, {"id": "pp017", "cat": "pp", "title": "الأزمة عدت", "text": "ق) الأزمة عدت وانا موجود\nوفي كل ازمة عندي اختبار\nإن كان اتون او جب اسود\n«الرب صالح» احلى شعار\n\n1- انا كنت بسمع عنك\nوعيني مش شايفاك\nالأزمة خلت عيني\nتشوفك واجري وراك\n\nق) الأزمة عدت وانا موجود\nوفي كل ازمة عندي اختبار\nإن كان اتون او جب اسود\n«الرب صالح» احلى شعار\n\n2- جميل من يوم ما عرفتك\nوفي الشدة انا بلاقيك\nناصفني وجاي في صفي\nوانا بتشرف بيك\n\nق) الأزمة عدت وانا موجود\nوفي كل ازمة عندي اختبار\nإن كان اتون او جب اسود\n«الرب صالح» احلى شعار\n\n3- مسنود ورافع ايدي\nوبعظم اسم يسوع\nالعدو تم خرابه\nهاقولها بصوت مسموع\n\nق) الأزمة عدت وانا موجود\nوفي كل ازمة عندي اختبار\nإن كان اتون او جب اسود\n«الرب صالح» احلى شعار"}, {"id": "pp018", "cat": "pp", "title": "الاعداء حواليَّ", "text": "1- الأعداء حواليَّ\nوانا واقف بإيديَّ\nاكشف عن عينيَّ\nواحفظني وباركني\n\nق) لن اطلقك\nلن اتركك\nإن لم تباركني\nلن اطلقك\n\n2- نصبتلك سلم\nومعاك راح اتكلم\nلا تعود تتألم\nمن عيسو يا ابني\n\nق) لن اطلقك\nلن اتركك\nإن لم تباركني\nلن اطلقك\n\n3- لابان بيطاردني\nعيسو منتظرني\nلكن انت واعدني\nانك تباركني\n\nق) لن اطلقك\nلن اتركك\nإن لم تباركني\nلن اطلقك\n\n4- جدد لي وعدك\nقولي انا معك\nده البركة في رضاك\nارضى وباركني\n\nق) لن اطلقك\nلن اتركك\nإن لم تباركني\nلن اطلقك\n\n5- العالم شاغلني\nخدعته وخدعني\nوراحيل ماتت مني\nارضى وباركني\n\nق) لن اطلقك\nلن اتركك\nإن لم تباركني\nلن اطلقك"}, {"id": "pp019", "cat": "pp", "title": "الخطية يا ما اقساها", "text": "1- الخطية يا ما اقساها\nيا ويل اللي يعيش معاها\nاوعى يا مؤمن تغوها\nبتودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n2- الخطية حالتها تهين\nوفاعلها من الهالكين\nومسكنها جهنم بيقين\nبتودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n3- الخطية ما ابشعها\nإلى جهنم مرجعها\nاوعى يا مؤمن تطاوعها\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n4- الخطية عار الشعوب\nوفاعلها دايماً مغلوب\nوالبُعد عنها هو المطلوب\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n5- الخطية ملهاش مثيل\nخلت قايين ذبح هابيل\nوالرب طرده وصار ذليل\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n6- الخطية توهت قايين\nوجعلته هارب كالمجانين\nطول حياته داير حزين\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n7- الخطية ملهاش امان\nخلت آدم عايش عريان\nوالرب طرده من البستان\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n8- الخطية أغوت حوا\nفي نظرها كانت حلوة\nرمت العالم في بلوى\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n9- الخطية ابكتهم بدمع العين\nيادي الفضيحة صاروا عريانين\nواتستروا بورق التين\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n10- الخطية اغوت شمشون\nوادخلته جوة السجون\nوصار مقلع العيون\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n11- الخطية حالتها شر\nوفاعلها دايماً ينضر\nاوعى يا مؤمن بيها تتغر\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n12- الخطية فضاحة \nومتخليش حد في راحة\nوفاعلها كله نجاسة \nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n13- الخطية دكتها بلاد\nوحرمتهم من أكل الزاد\nوشرها يقعد في الاولاد\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n14- الخطية خربت بيوت\nوعارها يقعد بثبوت\nالنفس اللي تخطي تموت\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n15- الخطية وسواس\nوغلبت اغلب الناس\nاللي تمسه يقعد محتاس\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n16- الخطية تجلب العار\nوتنزل عالي المقدار\nترميه في هاوية ماليها قرار\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n17- الخطية ضربت داود\nفي لحظة بقى ليها مشدود\nكسر الوصية وصار في جحود\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار\n\n18- الخطية اغوت سليمان\nتوهته في جب النسوان\nارجع يا خاطي للديان\nدي تودي النار\n\nق) (دي تودي النار)2\nالخطية بتودي النار\nوابعد عنها\nبتودي النار"}, {"id": "pp020", "cat": "pp", "title": "الدنيا دايماً", "text": "ق) الدنيا دايماً ليه تملي مضلمة\nلو نورت لحظة وتبقى مغيمة\nانت يا رب نور حياتي ودنيتي\nومعاك تفتح ابواب كتير متقفلة\n\n1- انت اللي عندك راحة من كل التعب\nوحدك معاك كل الأمان وحدك يا رب\nوحكمتك يا إلهنا دي ليها العجب\nدايماً بتيجي تحل كل مشكلة\n\nق) الدنيا دايماً ليه تملي مضلمة\nلو نورت لحظة وتبقى مغيمة\nانت يا رب نور حياتي ودنيتي\nومعاك تفتح ابواب كتير متقفلة\n\n2- الشكر ليك والحمد ليك والمجد ليك\nنورك معايا في كل السكك\nوعلى عرش قلبي انت وحدك الملك\nوامور حياتي بين ايديك متسلمة\n\nق) الدنيا دايماً ليه تملي مضلمة\nلو نورت لحظة وتبقى مغيمة\nانت يا رب نور حياتي ودنيتي\nومعاك تفتح ابواب كتير متقفلة\n\n3- انت اللي عارف اسرار القلوب\nدايماً بتقبل كل خاطي لو يتوب\nرجعني ليك واغفر وسئل كل الذنوب\nوانا روحي لو تنساك تكون متحطمة\n\nق) الدنيا دايماً ليه تملي مضلمة\nلو نورت لحظة وتبقى مغيمة\nانت يا رب نور حياتي ودنيتي\nومعاك تفتح ابواب كتير متقفلة"}, {"id": "pp021", "cat": "pp", "title": "الرب لي راعي", "text": "1- الرب لي راعي\nفلا يعوزني شئ\nيسكنني مراعياً خُضراً\nإلهي الحي\n\nق) الرب راعي\nالرب رعي\nفيه غدت كفايتي\nفلم يعوزني شئ\n\n2- لماء راحة\nيوردني مولاي\nيرد نفسي\nهادياً لبره إياي\n\nق) الرب راعي\nالرب رعي\nفيه غدت كفايتي\nفلم يعوزني شئ\n\n3- إن سرت في الوادي\nوادي ظلال الموت\nفلا اخاف ابداً\nانت معي بدوت\n\nق) الرب راعي\nالرب رعي\nفيه غدت كفايتي\nفلم يعوزني شئ\n\n4- عكازك القوي\nيا رب يحميني\nعصاك لي\nمرشده بها تعزيني\n\nق) الرب راعي\nالرب رعي\nفيه غدت كفايتي\nفلم يعوزني شئ\n\n5- مائدة إلهنا\nلي رتب المنان\nأمام من ضايقني\nفالحمد للرحمن\n\nق) الرب راعي\nالرب رعي\nفيه غدت كفايتي\nفلم يعوزني شئ\n\n6- بدهنك النقي\nمسحت لي رأسي\nبنعمة منك سمت ريا\nغدت كأسي\n\nق) الرب راعي\nالرب رعي\nفيه غدت كفايتي\nفلم يعوزني شئ\n\n7- خيراً ورحمة\nلي مدى العمر\nوبيت ربي مسكني\nإلى مدى الدهر\n\nق) الرب راعي\nالرب رعي\nفيه غدت كفايتي\nفلم يعوزني شئ"}, {"id": "pp022", "cat": "pp", "title": "السما حلوة", "text": "ق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n1- في السماء ملايكة وقوات\nطغمات ألوف ربوات ربوات\nبيقدموا عنا صلوات\nامام عرش رب القوات\n\nهنا هموم واتعاب وآلام\nهنا دموع واخبار حروب\nلكن في السماء افراحنا تدوم\nويا حبيب القلب يسوع\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n2- يا فرح المؤمن بالسماء\nبعد نهاية غربته هنا\nهايعيش في المجد للأبد\nاللي اعده الرب لنا\n\nيلبس في السماء صورة جديدة\nلا فيها خطأ ولا شر\nلكن جسده نوراني ممجد\nويعيش في سعادة للأبد\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n3- ونشوف العذراء حبيبتنا\nام النور مريم شفيعتنا\nمع الملائكة بتصلي\nلحل كل مشاكلنا\n\nونشوف كاروزنا مارمرقس\nوسريع الندهة مارجرجس\nوابو سيفين والأمير تادرس\nومارمينا والبابا كيرلس\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n4- ونشوف اول الشهداء\nرئيس الشمامسة اسطفانوس\nويا سحابة الشهداء\nوأيضاً القوي اباسخيرون\n\nونشوف الانبا بيشوي\nوابو الرهبان انبا انطونيوس\nوابو مقار والانبا باخوميوس\nوانبا شنودة وانبا مكاريوس\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n5- ونشوف قزمان ودميان\nوالانبا برسوم العريان\nوانبا رويس وانبا آبرام\nوابونا يسى ويسطس كمان\n\nونشوف بطاركة عظماء\nساجدين ليسوع فوق في السماء\nانبا باسيليوس وانبا اثناسيوس\nويوسقوروس وانبا ثاؤفيلوس\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n6- ونشوف انبا موسى الاسود\nومكسيموس ودوماديوس\nوانبا بموا وايسيذوروس\nويحنس كاما وانبا يؤانس\n\nونشوف في السماء آباء سواح\nبيقدموا للناس شفاعات\nانبا كاراس وانبا توماس\nانبا ميصائيل وانبا يوساب\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n7- انبا هيرمينا وانبا نوفير\nوانبا بولا وانبا غاليون\nوانبا هدرا وانبا بفنوتيوس\nوالقس الحبشي تكلا هيمانوت\n\nونشوف الشهيدة دميانة\nوالاربعين عذراء معاها\nوالأم رفقة وهيلانة\nوبربارة ويوليانة\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n8- ونشوف يوستينا وفيرينا\nومهرائيل واريبسيما\nواناسيمون وفيبرونيا\nوسوسنة وايريني\n\nفي السماء جيوش ربوات\nملائكة وقديسين وقديسات\nبيقدموا للناس شفاعات\nأمام عرش الرب الإله \n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n9- في السماء قدام يسوع\nده الكل ساجد في خشوع\nللرب ملك الملوك\nصارخين قائلين قدوس قدوس\n\nقدوس قدوس رب الصباؤوت\nليك العظمة وليك السجود\nالمجد والكرامة لإسم يسوع\nمخلصنا محيي النفوس\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n10- افراح السماء ملهاش مثيل\nلأنها ويا المسيح\nومعاه هنحيا في تسبيح\nويا الملائكة والقديسين\n\nجاهد على الأرض هنا\nوخلي عينيك ع السماء\nونفذ وصايا ربنا\nتورث المجد إلى الأبد\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع\n\n11- الدنيا فانية ومتسواش\nلحظة هاتعيشها مع الآب\nجاهد وإكنز للسماء\nلما تروح تلاقيه هناك\n\nفرصة عظيمة لك من الآب\nربك يسوع اللي فداك\nبيقولك توب بسرعة الآن\nيا ابني قبل فوات الآوان\n\nق) والسماء حلوة وجميلة\nلا فيها عطش ولا جوع\nفيها سنرى حبيبنا\nوخلصنا الرب يسوع"}, {"id": "pp023", "cat": "pp", "title": "الشهد يقطر", "text": "1- الشهد يقطر\nمن شفتيه\nوجلال المُلك\nباين عليه\n\n2- رجليه تشبه\nنحاس مسبوك\nمكتوب على فخذه\nملك الملوك\n\n3- وشعره ابيض\nكأنقى صوف\nوصدره رصع\nلؤلؤ موصوف\n\n4- جماله الباهر\nسابي القلوب\nعريس مبارك\nخالي العيوب\n\n5- وبدمه دخل\nقدس الاقداس\nفوجد فداء\nلجميع الناس\n\n6- والآن جالس\nعن اليمين\nيترأى ويشبع\nفي المؤمنين\n\n7- والآن يأتي\nمن اعلى سماه\nوبمركباته\nياخدنا معاه"}, {"id": "pp024", "cat": "pp", "title": "الصوم الكبير", "text": "ق) الصوم الكبير \nايامه 55\nيسوع صام 40\nاسبوعين استعداد وآلام\n\n1- الاحد الاول احد الكنوز\nوالاحد الثاني احد التجربة\nوالاحد الثالث الابن الضال\nوالاحد الرابع احد السامرية\n\nق) الصوم الكبير \nايامه 55\nيسوع صام 40\nاسبوعين استعداد وآلام\n\n2- الاحد الخامس احد الوحيد\nوالاحد السادس احد المولود اعمى\nوالاحد السابع احد الشعانين\nوالاحد الثامن عيد القيامة\n\nق) الصوم الكبير \nايامه 55\nيسوع صام 40\nاسبوعين استعداد وآلام\n\n3- وفي احد الشعانين\n وعيدي الصليب\nبيصلي ابونا دورة\n 12 انجيل\nالهيكل الكبير\nالعذراء وغبريال\nميخائيل ومارمرقس\nالرسل ومارجرجس\n\nق) الصوم الكبير \nايامه 55\nيسوع صام 40\nاسبوعين استعداد وآلام\n\n4- والانبا انطونيوس\nوالباب البحري\nوامام اللقان\nوالباب القبلي\nويوحنا المعمدان\nنهاية الدورة\nفي رفع بخور باكر\nبعد افنوتي ناي نان\n\nق) الصوم الكبير \nايامه 55\nيسوع صام 40\nاسبوعين استعداد وآلام"}, {"id": "pp025", "cat": "pp", "title": "العدل شاور", "text": "1- العدل شاور وقال\nاجرة الخطية موت\nصرخ من جوايا سؤال\nمين عن خطيتي يموت؟\n\nق) محكمة العدل السماوية\nحكمت على عصياني\nخاين انا خاين كسرت الوصية\nلكن يسوع نجاني\n\n2- العدل علَّا كمان صوته\nوقال مين هايوفي الدين\nما يغطي عار الخطية\nلا ولا حتى ورق التين\n\nق) محكمة العدل السماوية\nحكمت على عصياني\nخاين انا خاين كسرت الوصية\nلكن يسوع نجاني\n\n3- الحب اتنازل واتجسد\nوخد صورة انسان\nصُلِب ومات. بس قام واتمجد\nمبقاش للعدو سلطان\n\nق) محكمة العدل السماوية\nحكمت على عصياني\nخاين انا خاين كسرت الوصية\nلكن يسوع نجاني"}, {"id": "pp026", "cat": "pp", "title": "العدو بيهدد", "text": "1- العدو بيهدد\nاحفظ جنودك\nاسند وشدد\nتمم وعودك\n\nق) اعبر إلينا\nبمعونة جديدة\nواملأ آوانينا\nدي الحرب شديدة \n\n2- شايف وعارف\nقلوب عبيدك\nزيل المخاوف\nومد ايدك\n\nق) اعبر إلينا\nبمعونة جديدة\nواملأ آوانينا\nدي الحرب شديدة \n\n3- وملناش غيرك\nانت قائدنا\nعنا بتحارب\nضامن نصرتنا\n\nق) اعبر إلينا\nبمعونة جديدة\nواملأ آوانينا\nدي الحرب شديدة \n\n4- وجدد لينا\nالملئ بروحك\nواملك علينا\nمن أجل جروحك\n\nق) اعبر إلينا\nبمعونة جديدة\nواملأ آوانينا\nدي الحرب شديدة \n\n5- يا شعب اطمن\nبيحارب عنك\nوالعدو لا يمكن\nها يقرب منك\n\nق) اعبر إلينا\nبمعونة جديدة\nواملأ آوانينا\nدي الحرب شديدة "}, {"id": "pp027", "cat": "pp", "title": "العدرا هي امي", "text": "ق) العذراء هي امي\nفي السماء تصلي عني\nشفاعتها يا ناس قوية\nامام يسوع فاديَّ\n\n1- اناديها وانا محتاج\nتجيني بالبركات\nويفرح قلبي ربي\nبصلاتها على الدوام\n\nق) العذراء هي امي\nفي السماء تصلي عني\nشفاعتها يا ناس قوية\nامام يسوع فاديَّ\n\n2- اناديها وسط الاحزان\nتجيني بالسلام\nويفرح قلبي ربي\nويملاني تعزيات\n\nق) العذراء هي امي\nفي السماء تصلي عني\nشفاعتها يا ناس قوية\nامام يسوع فاديَّ\n\n3- اناديها وسط الضيقات\nتتشفع عند الآب\nينقذني من الأزمات\nوانال البركات\n\nق) العذراء هي امي\nفي السماء تصلي عني\nشفاعتها يا ناس قوية\nامام يسوع فاديَّ\n\n4- اناديها وسط الامراض\nتشفعلي عند الآب\nوبكلمة واحدة منه\nانال نعمة وشفاء\n\nق) العذراء هي امي\nفي السماء تصلي عني\nشفاعتها يا ناس قوية\nامام يسوع فاديَّ\n\n5- كنيستنا القبطية\nعظيمة يا ناس قوية\nبتكرمك يا مريم\nيا طاهرة ونقية\n\nق) العذراء هي امي\nفي السماء تصلي عني\nشفاعتها يا ناس قوية\nامام يسوع فاديَّ"}, {"id": "pp028", "cat": "pp", "title": "اللي فداني قال لي", "text": "1- اللي فداني قال لي\nمغفورة لك خطاياك\nسترت كل عيوبي\nودم صليبي غطاك\n\nطرحت كل ذنوبي\nفي أعماق المحيطات\nغني وافرح يا ابني\nانا وحدي فداك\n\n2- اللي فداني قال لي\nبنفسي هاكون وياك\nوفي كل خطوة تسيرها\nهأقود انا خُطاك\n\nفي اتون او جُب اسود\nتلاقيني انا مستنيك\nعظَّم اسمي دوماً\nانا وحدي حماك\n\n3- اللي شفاني قال لي\nانا عندي ليك بلسم\nاداوي اجبر اعصب\nواشفي الروح كمان\n\nما عليَّ حاجة صعبة\nولا فيه شئ مستحيل\nثق دوماً في شخصي\nانا صاحب السلطان\n\n4- اللي فداني قال لي\nسكيب من غير حدود\nاعمار تنادي اغمار\nوروحي فيك يا يسوع\n\nاسراري اعلنها ليك\nوبمجدي راح اغطيك\nوالتسبيح عليك عظمني\nانا الله المعبود"}, {"id": "pp029", "cat": "pp", "title": "المعونة جاية", "text": "ق) المعونة جاية\nافرح وقول آمين\nطوباك يا ابو قلب شاكر\nمسنود على المعين\n\n1- المعونة جاية\nفي الكلمة وبالوعود\nتحبس جليات في ايدك\nبأسم رب الجنود\n\nق) المعونة جاية\nافرح وقول آمين\nطوباك يا ابو قلب شاكر\nمسنود على المعين\n\n2- المعونة جاية \nاتشدد وارفع ايديك\nتملك كل الاراضي\nاللي تدوسها قدميك\n\nق) المعونة جاية\nافرح وقول آمين\nطوباك يا ابو قلب شاكر\nمسنود على المعين\n\n3- المعونة جاية\nاصرخ وقول يسوع\nاصنع امور عظيمة\nواتدخل في الموضوع\n\nق) المعونة جاية\nافرح وقول آمين\nطوباك يا ابو قلب شاكر\nمسنود على المعين"}, {"id": "pp030", "cat": "pp", "title": "إله النعمة دعاني", "text": "1- إله النعمة دعاني\nمن وسط العالم ونداني\nوبصوته الحلو قالهالي\nده انت ابني حبيبي وغالي\n\nق)\n ده إلهي كامل الاوصاف\nده مسيحي مانح الخلاص\n\n2- إله النعمة فرحني\nمن بعد الحيرة ريحني\nوبكلامه أسرني\nوبحُبه الغالي شجعني\n\nق)\n ده إلهي كامل الاوصاف\nده مسيحي مانح الخلاص\n\n3- إله النعمة بيرعاني\nولا عمره في يوم هينساني\nوفي مرعى خُضرة يربضني\nولمية حلوة يوردني\n\nق)\n ده إلهي كامل الاوصاف\nده مسيحي مانح الخلاص\n\n4- إله النعمة ده ابويا\nمن حقي ارنم هليللويا\nيا عزوة شعبي يا هنايا\nلحد ما اوصل سمايا\n\nق)\n ده إلهي كامل الاوصاف\nده مسيحي مانح الخلاص"}, {"id": "pp031", "cat": "pp", "title": "إله أمانة", "text": "1- إله امانة لا جور فيه\nصديق وعادل زيه مافيش\nده حبيبي يا ناس رفع القصاص\nترسي وخلاصي ورفع لي راسي\n\n2- إله حاميني في يوم الضيق\nعينه عليَّ طول الطريق\nدايماً يسندني ويطمن قلبي\nده يسوع حبيبي عزي ونصيبي\n\n3- إله رفعني في الأزمات\nومالي حياتي بالتعزيات\nدايماً بقربي يسوع ربي\nده يسوع حبيبي عزي ونصيبي\n\n4- إله وعدني بالبركات\nوبتحلى ليه الترنيمات\nانا عايش بيه دايماً أعليه\nده يسوع حبيبي عزي ونصيبي"}, {"id": "pp032", "cat": "pp", "title": "إله لا قبلك", "text": "ق) إله لا قبلك ولا بعدك\nمين تاني إله ؟\nقدزوس مهوب انت في مجدك\nيا ابن الله \nنؤمن بيك ونحبك\nانت الحياة\n(يسوع) 3 الله معانا\n\n1- ملك الملوك ولا غيرك\nوالكل عايش من خيرك\nيا سيد الكل احنا عبيدك\nنصرتنا فيك وحمانا 2\n\nق) إله لا قبلك ولا بعدك\nمين تاني إله ؟\nقدزوس مهوب انت في مجدك\nيا ابن الله \nنؤمن بيك ونحبك\nانت الحياة\n(يسوع) 3 الله معانا\n\n2- جبار عظيم ولا مثلك\nفي قدرة ايدك وعملك\nبالحب ملكت على شعبك\nوروحك فاض وملانا 2\n\nق) إله لا قبلك ولا بعدك\nمين تاني إله ؟\nقدزوس مهوب انت في مجدك\nيا ابن الله \nنؤمن بيك ونحبك\nانت الحياة\n(يسوع) 3 الله معانا\n\n3- وحدك ربي صاحب سلطان\nمالي حياتنا سلام وامان\nحل واملانا بنعمة الآن\nاسس ملكوتك جوانا 2\n\nق) إله لا قبلك ولا بعدك\nمين تاني إله ؟\nقدزوس مهوب انت في مجدك\nيا ابن الله \nنؤمن بيك ونحبك\nانت الحياة\n(يسوع) 3 الله معانا"}, {"id": "pp033", "cat": "pp", "title": "إلى مين يا رب", "text": "1- إلى مين يا رب إلى مين نلجأ انت وحدك انت الملجأ\nعندك آمان عندك سلام\nانت النجاة انت الضمان\n\n2- كيف يا رب كيف ننجو\nإن لم نخلص إن لم ندنوا\nفدنوا منا مِل إلينا\nافتقدنا وإرحمنا\n\n3- اجذبنا يا رب اجذبنا إليك\nفنحن في شوق إليك\nانني اشتاق إلى رؤياك\nإلى لُقاك إلى بهاك\n\n4- عندما تأتي تأتي الأفراح\nتبعد عنا كل الجراح\nتشدو لك كل النفوس\nوتسبحك آيا قدوس"}, {"id": "pp034", "cat": "pp", "title": "ام الشهداء جميلة", "text": "1-ام الشهداء جميلة\nام الشرفاء نبيلة\nعبرت بحر الالامات\nحفظت بدماها الحق قويم\n\nق) أعروس الفادي القبطية\nوضياء بلادي المصرية\nبمحبة قلبي النارية\nأهواكي يا ارثوذكسية\n\n2- يا امي حبك احياني\nوآلامك بذرة ايماني\nجزت أمرَّ الازماني\nوخرجتي خروج الشجعان\n\nق) أعروس الفادي القبطية\nوضياء بلادي المصرية\nبمحبة قلبي النارية\nأهواكي يا ارثوذكسية\n\n3- ضربوكي الأعداء طردوكي\nسجنوكي وأيضاً قتلوكي\nوطعام وحوش جعلوكي\nولكل عذاب دفعوكي\n\nق) أعروس الفادي القبطية\nوضياء بلادي المصرية\nبمحبة قلبي النارية\nأهواكي يا ارثوذكسية\n\n4- يا أمي كم كنتي امينة\nوبحب عريسك مفتونة\nاسراره عندك مكنونة\nوبقوته انتي مصونة\n\nق) أعروس الفادي القبطية\nوضياء بلادي المصرية\nبمحبة قلبي النارية\nأهواكي يا ارثوذكسية\n\n5- ما احلى امي المطرودة\nمن اجل الفادي وعبيده\nيا سعدك معطيكي وداده\nمن ينهض بيعة اجداده\n\nق) أعروس الفادي القبطية\nوضياء بلادي المصرية\nبمحبة قلبي النارية\nأهواكي يا ارثوذكسية\n\n6- يا ليت فؤادي يهواكي\nكي احيا في ظل حماكي\nواطارد دائماً اعدائك\nواجدد ايام صباكي\n\nق) أعروس الفادي القبطية\nوضياء بلادي المصرية\nبمحبة قلبي النارية\nأهواكي يا ارثوذكسية\n\n7- يا امي اثارك في الوادي\nوحنانك يغلي في فؤادي\nهأعهد وفائي وودادي\nأن اخدم بيعة اجدادي\n\nق) أعروس الفادي القبطية\nوضياء بلادي المصرية\nبمحبة قلبي النارية\nأهواكي يا ارثوذكسية"}, {"id": "pp035", "cat": "pp", "title": "آمين تعال", "text": "1- امين تعال \nايها الرب يسوع\nامين تعال\nقلوبنا اشتاقت للرجوع\n\nق) منتظرينك\n حسب وعودك\nقُلتَ سأتي سريعاً\n آمين\n\n2- نراك بمجدك\nعلى السحاب المنير\nتجعلنا مثلك\nوفي طرفة عين إليك نطير\n\nق) منتظرينك\n حسب وعودك\nقُلتَ سأتي سريعاً\n آمين\n\n3- نفرح بقربك\nونشوف آثار الجروح\nعلامة حبك\nلنا يا حبيب الروح\n\nق) منتظرينك\n حسب وعودك\nقُلتَ سأتي سريعاً\n آمين\n\n4- نسعد بشخصك\nونكون معاك كل حين\nيجمعنا عُرسك\nمع جماعة المفديين\n\nق) منتظرينك\n حسب وعودك\nقُلتَ سأتي سريعاً\n آمين\n\n5- ننسى اتعابنا\nولا يكون هناك أنين\nحوالين عريسنا\nدوماً نكون فرحانين\n\nق) منتظرينك\n حسب وعودك\nقُلتَ سأتي سريعاً\n آمين\n\n6- اشواق قلوبنا\nنلقاها ونشوفك بالعين\nيا فادي نفوسنا\nيا حلو يا طيب يا أمين\n\nق) منتظرينك\n حسب وعودك\nقُلتَ سأتي سريعاً\n آمين"}, {"id": "pp036", "cat": "pp", "title": "إن أُنسى", "text": "1- إن أُنسى من امي الحنون\nاحضان ربي لي تصون\nأعز عنده البنون\nفكيف ينساني ؟\n\nق) فكيف ينساني ؟\nفكيف ينساني ؟\nإن نسيت الأم الرضيع\nربي لا ينساني\n\n2- إن يُنسى من أم ولد\nيبقى له الرب سند\nمُحصى لي شعري بالعدد\nفكيف ينساني ؟\n\nق) فكيف ينساني ؟\nفكيف ينساني ؟\nإن نسيت الأم الرضيع\nربي لا ينساني\n\n3- عصفوراً دوراً إن سقط\nيُنسى من الناس فقط\nيسوع لا ينساه قط\nفكيف ينساني ؟\n\nق) فكيف ينساني ؟\nفكيف ينساني ؟\nإن نسيت الأم الرضيع\nربي لا ينساني\n\n4- من اجلي الشوك اقتنى\nكذاك بالطير اعتنى\nافضل منهما انا\nفكيف ينساني ؟\n\nق) فكيف ينساني ؟\nفكيف ينساني ؟\nإن نسيت الأم الرضيع\nربي لا ينساني"}, {"id": "pp037", "cat": "pp", "title": "انا الحقير", "text": "1- انا الحقير. صرت أمير\nالليلويا الليلويا\n2- ده مسك ايدي. رفعني سيدي\nالليلويا الليلويا\n\n3- انا الهالك. خلاني ملك\nالليلويا الليلويا\n4- شفاني بجروحه. اعطاني روحه\nالليلويا الليلويا\n\n5- اعطاني قوة. بالروح من جوة\nالليلويا الليلويا\n6- سندني بوعده. ودعاني لمجده\nالليلويا الليلويا\n\n7- قال لا تهتم. شارك بالدم\nالليلويا الليلويا\n8- شايل احمالي. ويقولي يا غالي\nالليلويا الليلويا\n\n9- وهبني الجنسية. السماوية\nالليلويا الليلويا\n10- أعد مكاني. وجاي ليَّ تاني\nالليلويا الليلويا\n\n11- ده هو وعدني. هايجي ياخدني\nالليلويا الليلويا\n12- وهعيش وياه. وانظر بهاه\nالليلويا الليلويا"}, {"id": "pp038", "cat": "pp", "title": "انا الصغير في إخوتي", "text": "1- انا الصغير في اخوتي والحدث في بيت ابي كنت راعياً غنم ابي ، يداي صنعت الأرغن ، واصابعي آلفت المزمار الليلويا\n\n2- من هو الذي يخبر سيدي ؟ هو الرب الذي يستجيب لجميع الذين يصرخون إليه ، هو ارسل ملاكه ورفعني من غنم ابي ، ومسحني بدهن مسحته الليلويا\n\n3- اخوتي حسان وكبار ، والرب لم يسر بهم ، خرجت للقاء الفلسطيني فلعنني بأوثانه الليلويا\n\n4- فأستليت سيفه الذي كان بيده ونزعت رأسه عنه ونزعت العار عن بني إسرائيل الليلويا"}, {"id": "pp039", "cat": "pp", "title": "انا خاطي وبدي اتوب", "text": "ق) انا خاطي وبدي اتوب\nانا خاطي وكلي ذنوب\n(انا خاطي)3\n\n1- يا ربي انا اللي طغيت\nوانت اللي طويل الروح\nارحمني انا اللي بديت\nوكفاية عليَّ النوح\n\nق) انا خاطي وبدي اتوب\nانا خاطي وكلي ذنوب\n(انا خاطي)3\n\n2- اللص اليمين ناداك\nقال اغفرلي يا قدوس\nفأنت برحمتك ورضاك\nفتحت لي الفردوس\n\nق) انا خاطي وبدي اتوب\nانا خاطي وكلي ذنوب\n(انا خاطي)3\n\n3- العشار قبلته إليك\nوغفرت له الآثام\nيا ربي اتكلت عليك\nاشفيني من الآلام\n\nق) انا خاطي وبدي اتوب\nانا خاطي وكلي ذنوب\n(انا خاطي)3\n\n4- الزانية غفرت لها\nلمَّا سكبت الدموع\nوالنازفة رأفت بها\nحين لمست ثوبك يا يسوع\n\nق) انا خاطي وبدي اتوب\nانا خاطي وكلي ذنوب\n(انا خاطي)3\n\n5- انا خاطي ذليل وأثيم\nوطبعي الخطأ علطول\nوأنت الرحمن الرحيم\nحرف من كلامك لا يزول\n\nق) انا خاطي وبدي اتوب\nانا خاطي وكلي ذنوب\n(انا خاطي)3\n\n6- نساني الشيطان وصاياك\nبعدني عن الإنجيل\nوجدت العالم أشواك\nوكل الحياة تضليل\n\nق) انا خاطي وبدي اتوب\nانا خاطي وكلي ذنوب\n(انا خاطي)3\n\n7- رحمتك ولا خطاياي\nاغفرلي انا المسكين\nمن شري وجهل صباي\nخايف من صوتك وحزين\n\nق) انا خاطي وبدي اتوب\nانا خاطي وكلي ذنوب\n(انا خاطي)3\n\n8- لا ترد النظر عني\nولا تغضب عليَّ يا ربي\nكن عوني فرحني\nمثل انسان غريب\n\nق) انا خاطي وبدي اتوب\nانا خاطي وكلي ذنوب\n(انا خاطي)3"}, {"id": "pp040", "cat": "pp", "title": "انا كنت فاكره انه ناسيني", "text": "1- أنا كنت فاكره انه ناسيني \nاتاري قصده يعزيني\nنظرة منه لمسة مني\nاتاريه شفاني روحه عزاني\n\n2- انا كنت فاكره انه تركني\nاتاري قصده يباركني \nنظرة منه لمسة مني\nاتاريه شفاني روحه عزاني\n\n3- انا كنت فاكره انه جرحني\nاتاري قصده يفرحني \nنظرة منه لمسة مني\nاتاريه شفاني روحه عزاني\n\n4- انا كنت فاكره انه كسرني\nاتاري قصده يجبرني \nنظرة منه لمسة مني\nاتاريه شفاني روحه عزاني\n\n5- انا كنت فاكره بعيد عني \nاتاري هو قريب مني\nنظرة منه لمسة مني\nاتاريه شفاني روحه عزاني"}, {"id": "pp041", "cat": "pp", "title": "انا مستنيك", "text": "1- انا مستنيك\nرب الارباب\nانا مستنيك\nتفتح لي الباب\n\nق) انا مستنيك\nرجايا فيك\nانا مستنيك\nورجايا فيك\n\n2- انا مستنيك\nيا إلهي لوحدك\nانا مستنيك\nتوفيني بوعدك\n\nق) انا مستنيك\nرجايا فيك\nانا مستنيك\nورجايا فيك\n\n3- انا مستنيك\nيا أعظم معلم\nانا مستنيك\nانا عايز اتعلم\n\nق) انا مستنيك\nرجايا فيك\nانا مستنيك\nورجايا فيك\n\n4- انا مستنيك\nكرامة لجروحك\nانا مستنيك\nتملاني بروحك\n\nق) انا مستنيك\nرجايا فيك\nانا مستنيك\nورجايا فيك\n\n5- انا مستنيك\nيا فايض بخيرك\nانا مستنيك\nمش عايز غيرك\n\nق) انا مستنيك\nرجايا فيك\nانا مستنيك\nورجايا فيك\n\n6- انا مستنيك\nكرامة للحربة\nانا مستنيك\nتحميني في الغربة\n\nق) انا مستنيك\nرجايا فيك\nانا مستنيك\nورجايا فيك"}, {"id": "pp042", "cat": "pp", "title": "انا مش ناسي", "text": "1- أنا مش ناسي الأيد الحلوة\nاللي من البُعد جابتني\nواللي برغم عيوبي وضعفي\nماجتش في يوم وسابتني\n\nق) انا قدام حُبك يا الهي\nمديون قلبي اسير\nانا قدام إحسانك عاجز\nقلبي عن التعبير\n\n2- انا مش ناسي ايديك يا راعيَّ\nوقت الخوف ضموني\nلما سلامي اتهدد فيَّ\nبكل حنان رفعوني\n\nق) انا قدام حُبك يا الهي\nمديون قلبي اسير\nانا قدام إحسانك عاجز\nقلبي عن التعبير\n\n3- انا مش ناسي ايدين فخاري\nعظيم ياما شكِّل فيَّ\nوهايفضل يرسم جوايا\nويبان مجده عليَّ\n\nق) انا قدام حُبك يا الهي\nمديون قلبي اسير\nانا قدام إحسانك عاجز\nقلبي عن التعبير"}, {"id": "pp043", "cat": "pp", "title": "انا مش هارجع", "text": "1- انا مش هرجع ابعد عنك\nانا مش هرجع تاني واسيبك\nجاي بدموع التوبة بقولك\nراجع تاني امسكني بإيدك\n\nق) عمري ما اخاف طول ما انت معايا\nكل اموري بسلم ليك\nانت ضامني وانت حمايا\nوالمستقبل مضمون بيك\n\n2- انت ضامن لي حياتي الجاية\nوفي مشوار الغربة حاميني\nوانت ضامن لي حياة ابدية\nوبترشدني وبتهديني\n\nق) عمري ما اخاف طول ما انت معايا\nكل اموري بسلم ليك\nانت ضامني وانت حمايا\nوالمستقبل مضمون بيك"}, {"id": "pp044", "cat": "pp", "title": "انا هاملا الكون ترنيم", "text": "ق) انا هاملأ الكون ترنيم\nواغاني لرب عظيم\nحررني في يوم وفداني\nوشراني بدم كريم\n\n1- راح اعلي صوتي بهتاف\nوفي وادي الموت مش هخاف\nمليان بأمان مطمن\nومعايا راعي الخراف\n\nق) انا هاملأ الكون ترنيم\nواغاني لرب عظيم\nحررني في يوم وفداني\nوشراني بدم كريم\n\n2- وراح اعلن بالتسبيح\nاني مِلك المسيح\nهأرفع ترنيمة ذبيحة\nحمد وشكر ومديح\n\nق) انا هاملأ الكون ترنيم\nواغاني لرب عظيم\nحررني في يوم وفداني\nوشراني بدم كريم\n\n3- صوتي هيوصل للناس\nيعلن اجمل إحساس\nفرحان ليسوع محبوبي\nاللي وهبني الخلاص\n\nق) انا هاملأ الكون ترنيم\nواغاني لرب عظيم\nحررني في يوم وفداني\nوشراني بدم كريم"}, {"id": "pp045", "cat": "pp", "title": "انا يا يسوع", "text": "1- انا يا يسوع\n انا انا الخاطي\nجيتلك بالدموع\n اسجدلك وأطاطي\nانا ذنوبي كتيرة \nوحياتي شريرة\nانا انا الخاطي\n\n2- إبليس عمَّال يجري ورايا \nيجري ليل ونهار\nويحلي الدنيا في عينيَّ \nويزين لي النار\nيا يسوع احميني\nمن ايده احميني\nانا انا الخاطي\n\n3- لا تغلق باب بيعتك\nفي وجهي يا ري\nانا عشمان في رحمتك\nتغفر ليَّ ذنبي\nضمد ليَّ جروحي\nوانعش فيَّ روحي\nانا انا الخاطي\n\n4- وانا رغم ان دائماً عاصي\nتعطف برضه عليَّ\nوقلبي مهما يكون قاسي\nقلبك فيه حنية\nسامحني يا ربي\nواغفر ليَّ ذنبي\nانا انا الخاطي"}, {"id": "pp046", "cat": "pp", "title": "انت ابونا ومحدش غيرك", "text": "ق) انت ابونا ومحدش غيرك\nيطهر قلبي يا فايض بخيرك\nامسك ايدك واتعلق بيك\nانت النجاة\n\n1- ابنك محتاج لنعمة منك\nتنير ظلامي تديني قوة\nواثبت علطول من غير رجوع\nلوحل الخطية\n\nق) انت ابونا ومحدش غيرك\nيطهر قلبي يا فايض بخيرك\nامسك ايدك واتعلق بيك\nانت النجاة\n\n2- يا رب انت اعز ما ليَّ\nانا جاي نادم على الخطية\nأبكي بدموع واقول يا يسوع\nارجوك ترحمني \n\nق) انت ابونا ومحدش غيرك\nيطهر قلبي يا فايض بخيرك\nامسك ايدك واتعلق بيك\nانت النجاة\n\n3- ساعدني ابدأ معاك يا ربي\nحياة جديدة من كل قلبي\nانسى اللي فات من الآلامات\nآلام الخطية\n\nق) انت ابونا ومحدش غيرك\nيطهر قلبي يا فايض بخيرك\nامسك ايدك واتعلق بيك\nانت النجاة\n\n4- ده انا بين ايديك عجينة طرية\nشكلني يا ربي يا اغلى ما ليَّ\nانت الخالق انت الصانع\nانا بيك متطمن\n\nق) انت ابونا ومحدش غيرك\nيطهر قلبي يا فايض بخيرك\nامسك ايدك واتعلق بيك\nانت النجاة\n\n5- ابليس بيحارب يا رب بقوة\nوالعالم يدي شهواته المُرة\nلكن انا بيك غالب يا حبيب\nانت الإله\n\nق) انت ابونا ومحدش غيرك\nيطهر قلبي يا فايض بخيرك\nامسك ايدك واتعلق بيك\nانت النجاة"}, {"id": "pp047", "cat": "pp", "title": "انت راعينا", "text": "1- القلب المحتاج لحنان\nيلقى مين غيرك يا يسوع\nوالنفس العطشانة امان\nتلقى مين غيرك ينبوع\n\nق) انت راعينا يسوع الفادي\nكل قلوبنا إليك بتنادي\nشكراً شكراً ليك يا يسوع\nمجداً مجداً ليك يا يسوع\n\n2- العالم مليان اوجاع\nمش عارف مين يشكي لمين\nوالخاطي العايش في صراع\nمين غيرك يا إلهي معين\n\nق) انت راعينا يسوع الفادي\nكل قلوبنا إليك بتنادي\nشكراً شكراً ليك يا يسوع\nمجداً مجداً ليك يا يسوع\n\n3- عند صليبك شُفت جراح\nواتحملت عشانا آلام\nيوم ما قبلتك قلبي ارتاح\nاول مرة اشعر بسلام\n\nق) انت راعينا يسوع الفادي\nكل قلوبنا إليك بتنادي\nشكراً شكراً ليك يا يسوع\nمجداً مجداً ليك يا يسوع\n\n4- تلقى الكسر قوام تداويه\nحتى المرض المر شافيه\nكل حزين متضايق مين\nمين غيرك هايحن عليه\n\nق) انت راعينا يسوع الفادي\nكل قلوبنا إليك بتنادي\nشكراً شكراً ليك يا يسوع\nمجداً مجداً ليك يا يسوع"}, {"id": "pp048", "cat": "pp", "title": "انت يا يسوع رب الارباب", "text": "ق) انت يسوع رب الارباب\nملجأ لينا في الضيقات\nنجي اولادك من الوباء\nومن كل شرور الارض\n\n1- ما انت حمانا يا ربي يسوع\nفي كل بقاع الارض\nوانت الحصن اللي بتحمينا\nمن كل ضرر او شر\n\nق) انت يسوع رب الارباب\nملجأ لينا في الضيقات\nنجي اولادك من الوباء\nومن كل شرور الارض\n\n2- انت طبيبنا واحنا اولادك\nملناش غيرك انت يا رب\nانت قدير على كل شئ\nولا يعسر قدامك امر\n\nق) انت يسوع رب الارباب\nملجأ لينا في الضيقات\nنجي اولادك من الوباء\nومن كل شرور الارض\n\n3- انت يا رب الراعي الصالح\nقود الأزمة انت يا رب\nانت صاحب يد قوية\nاحمي اولادك من الشر\n\nق) انت يسوع رب الارباب\nملجأ لينا في الضيقات\nنجي اولادك من الوباء\nومن كل شرور الارض\n\n4- انت يا رب وعدك لينا\nتبقى معانا طول الدهر\nانت ناقشنا على كفيك\nولا تنسانا في اي ظرف\n\nق) انت يسوع رب الارباب\nملجأ لينا في الضيقات\nنجي اولادك من الوباء\nومن كل شرور الارض\n\n5- انت يا رب إله قدير\nعلى السماء وعلى الأرض\nانت كلك حُب وخير\nمهما زاد شر البشر\n\nق) انت يسوع رب الارباب\nملجأ لينا في الضيقات\nنجي اولادك من الوباء\nومن كل شرور الارض\n\n6- انت يا رب برج حصين\nلأولادك إلى طول الدهر\nمهما ان كان الشر عظيم\nتنقذهم من كل خطر\n\nق) انت يسوع رب الارباب\nملجأ لينا في الضيقات\nنجي اولادك من الوباء\nومن كل شرور الارض\n\n7- انت يا رب إله الكون\nتقدر على كل امر\nمهما ان كان الامر خطير\nهاترفع وتشيل الهم\n\nق) انت يسوع رب الارباب\nملجأ لينا في الضيقات\nنجي اولادك من الوباء\nومن كل شرور الارض\n\n8- انت يا رب ليك المجد\nفي السماء وعلى الارض\nقدامك نسجد شاكرين\nافضالك يا اعظم أب\n\nق) انت يسوع رب الارباب\nملجأ لينا في الضيقات\nنجي اولادك من الوباء\nومن كل شرور الارض"}, {"id": "pp049", "cat": "pp", "title": "اوعى تخاف م الليل", "text": "1- اوعى تخاف م الليل وظلامه\nاوعى تخاف م الليل\nانا هأستر عمرك وايامه\nانا هأحمل وهشيل\n\nق) اوعى تخاف م الليل\nاو من سهم يطير\nاطمن انا اللي معاك\n\n2- اوعى تخاف م الصياد\nانا اللي هانجيك\nولا وباء ولا حتى الامراض\nانا هألمس واشفيك\n\nق) اوعى تخاف م الليل\nاو من سهم يطير\nاطمن انا اللي معاك\n\n3- شايف قلبك الملهوف\nوالمتعلق بيَّ\nهأطرد من قدامك الخوف\nوتشوف صُنع ايديَّ\n\nق) اوعى تخاف م الليل\nاو من سهم يطير\nاطمن انا اللي معاك"}, {"id": "pp050", "cat": "pp", "title": "اوهبني يا رب", "text": "1- أوهبني يا ربي\nتوبة نقية\nولحضنك ارجع\nوانسى ماضيَّ\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك\n\n2- انت راعيَّ\nفي الغربة ديَّ\nامسك ايديَّ\nلمجد الابدية\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك\n\n3- انت حاميني\nبقوة روحك\nاثبت كالصخرة\nبكلمة منك\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك\n\n4- انت طبيبي\nاشفي سقامي\nوزيل آلامي\nبلمسة منك\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك\n\n5- انت معيني\nفي وقت ضعفي\nوفي كل همومي\nانت تعزيني\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك\n\n6- انت تحررني\nمن كل خطية\nوتحرر اسري\nيا ربي وفاديَّ\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك\n\n7- انت تحولني \nبنعمة منك\nكسّر قيودي\nما هو انا ابنك\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك\n\n8-انت راجايا\nمصدر سلامي\nبدد ظلامي\nبعملك فيَّ\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك\n\n9- انت تسدد \nكل احتياجي\nاشبعني بيك\nواروي حياتي\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك\n\n10- انت تلبسني\nحُلة بهية\nبثمار الروح\nفي المعمودية\n\nق) ده انت ابويا\nواثق في حُبك\nاغفرلي لي ذنبي\nارحمني انا ابنك"}, {"id": "pp051", "cat": "pp", "title": "ايوة إلهي صالح", "text": "1- ايوة إلهي حي\nحبه ماله زي\nجه عشاني وخد مكاني\nوكان تدبيره صالح\n\nق) ايوة إلهي صالح\nإلهي أمين\nيشهد عنه امبارح\nوكل السنين\n\n2- أيوة إلهي قدير\nوضامن المصير\nهو سانيدي وماسك ايدي\nعلشان هو صالح\n\nق) ايوة إلهي صالح\nإلهي أمين\nيشهد عنه امبارح\nوكل السنين\n\n3- ايوة إلهي عظيم\nوفي العطا كريم\nفايض خيره ومفيش غيره\nدايماً هو صالح\n\nق) ايوة إلهي صالح\nإلهي أمين\nيشهد عنه امبارح\nوكل السنين\n\n4- ايوة ابرع جمال\nوصاحب الجلال\nفخري فيه وها اعليه\nوبعلن انه صالح\n\nق) ايوة إلهي صالح\nإلهي أمين\nيشهد عنه امبارح\nوكل السنين"}, {"id": "pp052", "cat": "pp", "title": "ايوة بقولك", "text": "1- ايوة بقولك وانت في ضيق\nاطلب في الحال شهيد عظيم\nاسمه مارجرجس الروماني\nده شفيع قوي امام المسيح\n\nيجي بحصانه بسرعة يجري\nده سريع الندهة ومعين\nوتنتهي كل ضيقاتك\nويكون المجد للمسيح\n\nق) رنم يا شعب جوة كنيستك\nمجد وسبح الإله\nنور الشمع ورتل وافرح\nبمارجرجس امير الشهداء\n\nده سريع الندهة دائماً يسمع\nكل اللي يطلب بإيمان\nيشفع ويصلي لينا دايماً\nاما يسوع ملك السماء\n\n2- ايوة بقولك وسط ظروفك\nيسوع إلهنا عينه عليك\nوقت همومك واحزانك\nيبعت مارجرجس يواسيك\n\nيسندك يا ابني ويعينك\nبحصانه يلف حواليك\nبشفاعته ليك هايفرح قلبك\nده انت ابنه الغالي عليه\n\nق) رنم يا شعب جوة كنيستك\nمجد وسبح الإله\nنور الشمع ورتل وافرح\nبمارجرجس امير الشهداء\n\nده سريع الندهة دائماً يسمع\nكل اللي يطلب بإيمان\nيشفع ويصلي لينا دايماً\nاما يسوع ملك السماء\n\n3- ايوة بقولك وانت في مرضك\nومهما ان كان مرضك خطير\nاطلب شفاعة مارجرجس\nده هو حبيب المسيح\n\nيشفع ويطلب من إلهنا\nايده قديرة واعظم طبيب\nبلمسة يشفيك من امراضك\nوالمجد يرجع للمسيح\n\nق) رنم يا شعب جوة كنيستك\nمجد وسبح الإله\nنور الشمع ورتل وافرح\nبمارجرجس امير الشهداء\n\nده سريع الندهة دائماً يسمع\nكل اللي يطلب بإيمان\nيشفع ويصلي لينا دايماً\nاما يسوع ملك السماء\n\n4- ايوة بقولك وقت خوفك\nإلهك فاتح ذراعيه\nيرسل مارجرجس الروماني\nفي الحرب يدافع يا ابني عليك\n\nيهرب الخوف ويحل سلام\nقوة يسوع مصدر امان\nبشفاعة امير الشهداء\nمارجرجس البطل الشجاع\n\nق) رنم يا شعب جوة كنيستك\nمجد وسبح الإله\nنور الشمع ورتل وافرح\nبمارجرجس امير الشهداء\n\nده سريع الندهة دائماً يسمع\nكل اللي يطلب بإيمان\nيشفع ويصلي لينا دايماً\nاما يسوع ملك السماء\n\n5- ايوة بقولك خليك واثق\nرغم اضهاد العالم ليك\nده إلهك قوي ورب قادر\nوهيصنع ليك المستحيل\n\nده انت في السماء ليك سحابة\nمن الشهداء والقديسين\nمنهم امير الشهداء\nمارجرجس الفارس الأمين\n\nق) رنم يا شعب جوة كنيستك\nمجد وسبح الإله\nنور الشمع ورتل وافرح\nبمارجرجس امير الشهداء\n\nده سريع الندهة دائماً يسمع\nكل اللي يطلب بإيمان\nيشفع ويصلي لينا دايماً\nاما يسوع ملك السماء"}, {"id": "pp053", "cat": "pp", "title": "ايوة شُفتك", "text": "1- ايوة شُفتك في التجارب\nوانت بتدربني احارب\nكنت خايف من النهاية\nشُفتك الاسد اللي غالب\n\n2- ايوة شُفتك في انحنائي\nواقف بتشكل انائي\nكنت فاكرك مش دوايا\nشُفتك العون اللي باقي\n\n3- ايوة شُفتك في الامام\nوقت لمَّا عدوي قام\nكنت فاكرك مش معايا\nوانت ماسك الزمام\n\n4- ايوة شُفتك وسط ضعفي\nوانت بتداوي وتشفي\nكنت بسأل على الحماية\nوانت بتحارب في صفي\n\n5- ايوة شُفتك في انكساري\nوانت بتغير مصاري\nكنت شاكك في العناية\nوانت بترد اعتباري"}, {"id": "pp054", "cat": "pp", "title": "باب السما مفتوح", "text": "ق) باب السماء مفتوح\nوالرب سامعه يناديني\nوانا شايفه قبالي\nيقولي اصبر يا ابني\n\n1- صابر على الآلام\nفي عالم ساده الظلام\nاسندني امنحني سلام\nمين ليَّ غيرك يحميني\n\nق) باب السماء مفتوح\nوالرب سامعه يناديني\nوانا شايفه قبالي\nيقولي اصبر يا ابني\n\n2- عابر وادي الدموع\nناظر إليك يا يسوع\nويقول امتى الرجوع\nإلى كنعان هاتوديني\n\nق) باب السماء مفتوح\nوالرب سامعه يناديني\nوانا شايفه قبالي\nيقولي اصبر يا ابني\n\n3- انا جيت إليك يا رب\nصرخت بنادي م القلب\nاشتد عليَّ الحرب\nربي انت اللي تقويني\n\nق) باب السماء مفتوح\nوالرب سامعه يناديني\nوانا شايفه قبالي\nيقولي اصبر يا ابني\n\n4- ابليس وجنوده ضدي\nأهواله وأخطاره حولي\nوجَّه سهمه لصدري\nربي انت قوي تحميني\n\nق) باب السماء مفتوح\nوالرب سامعه يناديني\nوانا شايفه قبالي\nيقولي اصبر يا ابني\n\n5- انا رايح للحبيب\nومعاه القلب يطيب\nمافيش بكاء ونحيب\nلما اوصل تلاقيني\n\nق) باب السماء مفتوح\nوالرب سامعه يناديني\nوانا شايفه قبالي\nيقولي اصبر يا ابني\n\n6- اشوف حبيب الروح\nواتأمل في الجروح\nانسى البكاء والنوح\nواسمع صوته يعزيني\n\nق) باب السماء مفتوح\nوالرب سامعه يناديني\nوانا شايفه قبالي\nيقولي اصبر يا ابني"}, {"id": "pp055", "cat": "pp", "title": "بالروح رحت السما", "text": "1- بالروح رحت السما \nلقيت ملايكة اطهار\nساجدين امام الملك\nفي تسبيح بإستمرار\nقلت يا ميخائيل يا غابرئيل\nيا سوريئيل اشفعوا فينا\n\n2- بالروح رحت السما\nلقيت رسل اطهار\nخدموا بالحب هنا\nوهناك امام عرش الإله\nقلت يا مار مرقس يا مار لوقا\nيا مار بولس اشفعوا فينا\n\n3- بالروح رحت السما\nلقيت اباء سواح\nساجدين قدام الحمل\nوعلى رؤسهم تيجان\nقلت انبا كاراس انبا توماس \nانبا ميصائيل اشفعوا فينا\n\n4- بالروح رحت السما\nلقيت ابطال شهداء\nلابسين تيجان إلهنا\nفرحين امام الآب\nقلت يا مارجرجس يا مارمينا\nيا أبو سيفين اشفعوا فينا\n\n5- بالروح رحت السما\nلقيت هناك شهيدات\nلابسين تيجان الفرح\nلعريسهم في السماء\nقلت يا دميانة يا بربارة \nيا يوستينا اشفعوا فينا\n\n6- بالروح رحت السما\nلقيت اباء رهبان\nساجدين امام الحمل\nبيقدموا صلوات\nقلت انبا انطونيوس انبا بولا\nانبا بيشوي اشفعوا فينا\n\n7- بالروح رحت السما\nلقيت بطاركة عظماء\nماسكين شواري ذهب\nبيبخروا للآب\nقلت انبا اثناسيوس انبا كيرلس\nانبا شنودة اشفعوا فينا\n\n8- بالروح رحت السما\nلقيت اساقفة ابرار\nلابسين ثياب الفرح\nحوالين عرش الإله\nقلت انبا ابرام انبا بموا\nانبا مينا اشفعوا فينا\n\n9- بالروح رحت السما\nلقيت كهنة بوقار\nلابسين ثياب ممجد\nفي فرح مع البار\nقلت ابونا يسطس ابونا يسى\nابونا عبد المسيح اشفعوا فينا\n\n10- بالروح رحت السما\nلقيت شمامسة اطهار\nبيرتلوا للملك\nتسابيح الفرح الحان\nقلت انبا رويس حبيب جرجس\nسيدهم بشاي اشفعوا فينا\n\n11- بالروح رحت السما\nلقيت اطفال في نقاء\nفرحين بجوار الحمل\nلابسين ثياب بيضاء\nقلت يا ابانوب يا قرياقص \nيا زكريا اشفعوا فينا"}, {"id": "pp056", "cat": "pp", "title": "بعد الموت مفيش فرصة", "text": "1- اوعى تقول انا لسة صغير\nلما اكبر راح اتوب واتغير\n(مين فينا ضامن ايامه\nليه تعند ده العمر قصير)2\n\nاوعى تأجل او تتأخر \nوتقول بكرة وبعده افكر\nيمكن دي تكون اخر فرصة\nلو ضاعت مش راح تتكرر\n\nق) بعد الموت مفيش فرصة\nبعد الموت اتقفل الباب\nوليه تضيع الفرصة\nويبقى نصيبك نار وعذاب\n\n2- كل فلوسك هنا هاتسيبها\nلا ارض ولا بيوت هتاخدها\nدي الدنيا هترجع لخالقها\n\nحاسب نفسك قبل ما تمشي\nولخطاياك تاني ماترجعشي\nجاهد علشان تقدر توصل\nوميراثك في السما مايضيعشي\n\nق) بعد الموت مفيش فرصة\nبعد الموت اتقفل الباب\nوليه تضيع الفرصة\nويبقى نصيبك نار وعذاب\n\n3- بينا وبين الموت ده مفيش\nقد ايه من العمر نعيش\nمهما طال عمرنا هنموت\nليه بنبيع الغالي برخيص\n\nفيه ناس ماتت وبتتمنى\nلحظة من عمرك او ثانية\nترجع فيه تقدم توبة\nفي الابدية هنا تتهنى\n\nق) بعد الموت مفيش فرصة\nبعد الموت اتقفل الباب\nوليه تضيع الفرصة\nويبقى نصيبك نار وعذاب\n\n4- شوف كام فرصة ضاعت منك\nوبيصبر عليك ولا همك\nليه تستهون بيه وبلطفه\nوحده هو اللي شايل همك\n\nاوعى تكون ميت بالروح\nاو مش عارف فين هتروح\nاوعى تقسي قلبك وارجع\nلسه باب ربنا مفتوح\n\nق) بعد الموت مفيش فرصة\nبعد الموت اتقفل الباب\nوليه تضيع الفرصة\nويبقى نصيبك نار وعذاب"}, {"id": "pp057", "cat": "pp", "title": "بقى انا استاهل", "text": "1- بقى انا استاهل انك\nتخبط على قلبي\nوانت بجلالك واقف قدامي\nوتقول افتح لي\n\nق) مين انا مين ؟\nيمكن نسيت انا مين !\nانا التراب افتكري يا نفسي\nانا التراب اياكي تنسي\n\n2- بقى انا استاهل اللي\nعملته من أجلي\nوانت بجلالك واقف مكاني\nوحامل ذنبي\n\nق) مين انا مين ؟\nيمكن نسيت انا مين !\nانا التراب افتكري يا نفسي\nانا التراب اياكي تنسي\n\n3- بقى انا استاهل كل اللي\nدُقته من أجلي\nوفي جلالك نفذ إعدامي\nمُن وأحييتني\n\nق) مين انا مين ؟\nيمكن نسيت انا مين !\nانا التراب افتكري يا نفسي\nانا التراب اياكي تنسي\n\n4- بقى انا استاهل انك\nتتجسد علشاني\nوانت بجلالك تشبه انساني\nوتجرب عيشتي\n\nق) مين انا مين ؟\nيمكن نسيت انا مين !\nانا التراب افتكري يا نفسي\nانا التراب اياكي تنسي\n\n5- أنا ولا استاهل\nاغفر لي يا ربي\nوانت بجلالك انسى لي آثامي\nوارحمني يا ربي\n\nق) مين انا مين ؟\nيمكن نسيت انا مين !\nانا التراب افتكري يا نفسي\nانا التراب اياكي تنسي"}, {"id": "pp058", "cat": "pp", "title": "بكمال قلبك", "text": "1- الإحسان والخير طبعك يا كريم\nقلبك كبير دايماً حنَّان ورحيم\n\nق) بكمال قلبك\nانت راعينا\nوبمهارتك\nايدك تهدينا\n\n2- حياتنا وكل ما فيها\nانت غناها وخيرها \nانت بتعتني بيَّ\nمن بداية السنة لآخرها\n\nق) بكمال قلبك\nانت راعينا\nوبمهارتك\nايدك تهدينا\n\n3- بيتنا المبني بإيدك\nمتبارك بيك يا أمين\nدايماً حارس مواعيدك\nوعنيك السهرانين\n\nق) بكمال قلبك\nانت راعينا\nوبمهارتك\nايدك تهدينا"}, {"id": "pp059", "cat": "pp", "title": "بيك افراحي", "text": "1- بيك افراحي ابتدأت\nوصبح لها طعم روحاني\nبيك يا يسوع المسيح\nبيك ألحاني امتلأت\nبكلام عن ربي فداني\nبيك يا يسوع المسيح\n\nمن قلبي اللي صبح مرتاح\nبعلن مبتدأ الافراح\nايوة انا دُقت ازاي\nقدامك تهرب احزاني\n\n2- بيك خطاياي اتغفرت\nودماك فوقي وستراني\nبيك يا يسوع المسيح\nبيك خطاياي انطرحت\nفي بحور كلها نسياني\nبيك يا يسوع المسيح\n\nبعلن مبتدأ التسبيح\nوالترانيم والصلاة هايفوح \nمنها عطر اللي فداني\n\n3- بيك الظلمة انطردت\nوالنور ابتدأ يملاني\nبيك يا يسوع المسيح\nبيك النعمة امتلكت\nفيَّ وبرك ده كساني\nبيك يا يسوع المسيح\n\nبالروح عربون الامجاد\nبعلن مبتدأ الأعياد\nواسجدلك والقلب يفيض\nويعود ويرنم تاني\n\n4- بيك الغلبة دي عملت\nنهضة وتجديد في كياني\nبيك يا يسوع المسيح\nبيك النفس اعتزت\nبصليب وخلاص مجاني\nبيك يا يسوع المسيح\n\nبالدم علامة العلامات\nبأعلن مبتدأ الهتافات\nيللا يا سماء اهتفي إنما\nبهتاف عالي وسلطان"}, {"id": "pp060", "cat": "pp", "title": "تحتار وتفكر", "text": "1- تحتار وتفكر تعالى لي\nانا عندي حلول\nاترك مشكلتك قولهالي\nانا بيك مشغول\n\nها أقدر على البحر بهيجانه\nوالعدو يسكت جوة لسانه\nتخطيطي هايظهر في آوانه\nوانا المسئول\n\n2- لو حتى اخوانك واصحابك\nفي الشدة سابوك\nومحدش خبط على بابك\nانا برضو ابوك\n\nاعرف اكفيك وارتبها\nتتفاجئ قوي من ترتيبها\nاصل انا بالتوقيت بحسبها\nمانتاش متروك\n\n3- سيب المستقبل ده عليَّ\nها املاه اناشيد\nاوعى تنسى ان لك فيَّ\nكل المواعيد\n\nانا حاطط ايدي على حياتك\nعارف داري بإحتياجاتك\nبس اضبط على وقتي اوقاتك\nفرحك هايزيد"}, {"id": "pp061", "cat": "pp", "title": "تختفي الأحزان", "text": "1- تختفي الاحزان في قربك\nيتشفي القلب اللي حبك\nتتعفي الروح اللي ملكك\nمن عقوبتها وديونها\n\nالديون انت دافعها\nوالحمول انت رافعها\nوالصلاة بتستمعها\nوالنفوس بتشيل همومها\n\nق) لو هموم سايدة وزايدة\nاو الحلول مش جايبة فايدة\nانت بتنجي وتنقذ\nيا معين\n\nيا معين ارحم حبايبك\nيا يسوع إظهر عجايبك\nخلي كل الدنيا تعرف\nانت مين\n\n2- مين يا رب ياخدنا منك\nولا مين يفصلنا عنك\nياللي شارينا بدمك\nيا اللي حاططنا في عيونك\n\nوبعنيك انت حارسنا\nراعي وبتحرس نفوسنا\nصون بيوتنا وكنايسنا\nمش هانطمن بدونك\n\nق) لو هموم سايدة وزايدة\nاو الحلول مش جايبة فايدة\nانت بتنجي وتنقذ\nيا معين\n\nيا معين ارحم حبايبك\nيا يسوع إظهر عجايبك\nخلي كل الدنيا تعرف\nانت مين\n\n3- يتمحي ويخلص مرارنا\nيمسي ليلنا يعود نهارنا\nطول ما فوق عتبة ديارنا\nدمك المرشوش علامة\n\nوالعلامة دي خلاصنا\nبالصليب رفعت راسنا\nوإن إسود جت تفترسنا\nالصليب هايكون حمانا\n\nق) لو هموم سايدة وزايدة\nاو الحلول مش جايبة فايدة\nانت بتنجي وتنقذ\nيا معين\n\nيا معين ارحم حبايبك\nيا يسوع إظهر عجايبك\nخلي كل الدنيا تعرف\nانت مين"}, {"id": "pp062", "cat": "pp", "title": "38 سنة", "text": "1- 38 سنة (وانا مطروح)2\nجسدي مفلوج (وفؤادي مجروح)2\nقُلت ليسوع انت مافيش غيرك\nقال قوم احمل سريرك\n\nق) ومن ساعتها و(انا مسرور)2\nيسوع ماسكني و(ماشي في النور)2\nقلبي معاك علطول يا فاديَّ\nماتسبنيش ابداً وحدي\n\n2- وانا مولود (في الدنيا دي اعمى)2\nولا شُفت النور (ولا دُقت الظلمة)2\nجاني يسوع أحسن إليَّ\nوبأيده الحلوة فتح لي عينيَّ\n\nق) ومن ساعتها و(انا مسرور)2\nيسوع ماسكني و(ماشي في النور)2\nقلبي معاك علطول يا فاديَّ\nماتسبنيش ابداً وحدي\n\n3- وانا كنت خاطي (مجرم واثيم)2\nلا برحم ارملة (ولا يتيم)2\nقُلت ليسوع انا انا حبيتك\nقال لي اليوم هاتعشى في بيتك\n\nق) ومن ساعتها و(انا مسرور)2\nيسوع ماسكني و(ماشي في النور)2\nقلبي معاك علطول يا فاديَّ\nماتسبنيش ابداً وحدي"}, {"id": "pp063", "cat": "pp", "title": "ثبت انظارك", "text": "1- إن كنت سمعت نداه\nع المية مشيت وياه\nليه تتلفت حواليك\nعينك خليها عليه\n\nق) ثبت انظارك فيه\nوحمولك سيبها عليه\nوفي وادي ظل الموت\nصلي حالاً تلاقيه\n\n2- إن شُفت بعينك نار\nصدق يطفيها البار\nاو جواها يمشيك\nزي الفتيان حواليك\n\nق) ثبت انظارك فيه\nوحمولك سيبها عليه\nوفي وادي ظل الموت\nصلي حالاً تلاقيه\n\n3- إن كنت في وقت أليم\nحواليك الشر عظيم\nايمانك باللي فاديك\nغالب لو تثبت فيه\n\nق) ثبت انظارك فيه\nوحمولك سيبها عليه\nوفي وادي ظل الموت\nصلي حالاً تلاقيه"}, {"id": "pp064", "cat": "pp", "title": "جالها ملاك", "text": "1- لما ملاك جالها وبشرها\nببشارة تفرح قلب\nقالت مريم لما اختارها\nانا عبدة وانا امة الرب\n\nق) جالها ملاك وفي ملئ زمان\nقالت سيدي هايصبح ابني\nقالت مريم منذ الآن\nكل الاجيال هاتطوبني\n\n2- قالت قلبي اكيد فرحان\nان هشوفك يا ابن الله\nقالت بس كلامها سُكات\nوفي قلبها كانت شايلاه\n\nق) جالها ملاك وفي ملئ زمان\nقالت سيدي هايصبح ابني\nقالت مريم منذ الآن\nكل الاجيال هاتطوبني\n\n3- قالت انا خاضعة لمولاي\nانا راضية ومش هسأل كيف\nكيف ربنا هايكون جوايا\nكيف فيَّ هيجوز السيف\n\nق) جالها ملاك وفي ملئ زمان\nقالت سيدي هايصبح ابني\nقالت مريم منذ الآن\nكل الاجيال هاتطوبني"}, {"id": "pp065", "cat": "pp", "title": "جاي وبسلم قلبي", "text": "1- جاي وبسلم قلبي يا ربي\nتارك كل اموري لديك\nبعلم ثقتي وبعلم حُبي\nمهما يكون انا خاضع ليك\n\nق) ايامي كلها في ايديك\nمش خايف من بكرة معاك\nده المستقبل كله لديك\nمضمون فيه الخير وياك\n\n2- ياللي بتدي القلب تملي\nوعد براحة طول الايام\nوعدك ليَّ راح يضمن لي\nجود ومراحم ويا سلام\n\nق) ايامي كلها في ايديك\nمش خايف من بكرة معاك\nده المستقبل كله لديك\nمضمون فيه الخير وياك\n\n3- نفسي حاميها بسور من نار\nروحك فيَّ يا رب ماليني\nولا يمكن في يوم احتار\nعلشان انت اللي بتهديني\n\nق) ايامي كلها في ايديك\nمش خايف من بكرة معاك\nده المستقبل كله لديك\nمضمون فيه الخير وياك\n\n4- ربي بحُبك تملي حياتي\nهأقضي حياتي متمسك بيك\nماشي معايا وانا في جهادي\nاصل انا ابنك وصنع ايديك\n\nق) ايامي كلها في ايديك\nمش خايف من بكرة معاك\nده المستقبل كله لديك\nمضمون فيه الخير وياك"}, {"id": "pp066", "cat": "pp", "title": "جايين نشتيكيلك", "text": "1- جايين نشتيكيلك\nمن قساوتنا\nرافعين لك قلوبنا\nاقبل توبتنا\n\nارفع غضبك عنا\nارحم جبلتنا\nده احنا تعبنا وقاسينا\nمن كُتر عنادنا\nكرحمتك يا رب وليس كخطايانا\n\n2- اشعل روحك فينا\nبتوبة تفوقنا\nنبكي وننحينيلك\nودموعنا تغرقنا\n\nافتح ابواب السما\nمطر علينا\nبالمراحم والرأفات\nتتعزي عنينا\nكرحمتك يا رب وليس كخطايانا\n\n3- ينابيع الخلاص\nتروي اراضينا\nتسبيح وهتاف\nيصبح اغانينا\n\nوالنوح والكآبة\nفرحة تكون لينا\nوالأحزان الاولى\nتتحول ترنيمة\nكرحمتك يا رب وليس كخطايانا"}, {"id": "pp067", "cat": "pp", "title": "جوة الطاحونة", "text": "ق) جوة الطاحونة\nوجدت معونة\nياما صليت يا بابا كيرلس\nباكر وعشية\n\n1- على الارض تنام\nفي هدوء وسلام\nحولت الطاحونة يا بابانا\nسماء روحانية\n\nق) جوة الطاحونة\nوجدت معونة\nياما صليت يا بابا كيرلس\nباكر وعشية\n\n2- في الأكل قراقيش\nأقول حتى مفيش\nمدام قلبك عمران يا بابانا\nالعيشة تبقى هنية\n\nق) جوة الطاحونة\nوجدت معونة\nياما صليت يا بابا كيرلس\nباكر وعشية\n\n3- تخبز القربان\nتصلي في كل آوان\nتنسخ في المكتوب يا بابانا\nعلى اللمبة السهرية\n\nق) جوة الطاحونة\nوجدت معونة\nياما صليت يا بابا كيرلس\nباكر وعشية\n\n4- في نصف الليل تسبيح\nالملايكة معاك تصيح\nبعد القداس يا بابانا\nتخرج في الصبحية\n\nق) جوة الطاحونة\nوجدت معونة\nياما صليت يا بابا كيرلس\nباكر وعشية\n\n5- وحوش البرية\nتركت كل أذية\nكانت معاك يا بابانا\nبمحبة حقيقية\n\nق) جوة الطاحونة\nوجدت معونة\nياما صليت يا بابا كيرلس\nباكر وعشية\n\n6- تصلي مع السواح\nوالرب معاك ارتاح\nومارمينا بحصانه يا بابانا\nبيلف البرية\n\nق) جوة الطاحونة\nوجدت معونة\nياما صليت يا بابا كيرلس\nباكر وعشية\n\n7- يا ساكن الجبال\nيا قاهرالاهوال\nفقت كل مثال يا بابانا\nشرفت البشرية\n\nق) جوة الطاحونة\nوجدت معونة\nياما صليت يا بابا كيرلس\nباكر وعشية\n\n8- اذكرنا على الدوام\nواطلب السلام\nمن الرب الحنَّان يا بابانا\nللبيعة الارثوذكسية\n\nق) جوة الطاحونة\nوجدت معونة\nياما صليت يا بابا كيرلس\nباكر وعشية"}, {"id": "pp068", "cat": "pp", "title": "حُبَّك غيَّر معنى", "text": "1- حبك غير معنى حياتي\nوكمل كل النقص بذاتي\nوبتقوي بروحك ضعفاتي\nانت نجاتي وعضدي وسندي\n\nوانت النغم بوتري وعودي\nالكلمة اللي على شفايفي موجودة\nهدفي انت وسبب وجودي\nونفسي بشخصك شبعانة\n\nق) وحدك انت اللي بتستاهل \nاعيشلك عمري وزماني\nوحدك انت اللي بتستاهل\nياللي دمك غطاني\n\n2- السماء والارض بتشهد عنك\nكل الحكمة فيك ومنك\nكل الكون بيهتف انك\nانت الخالق انت الباري\n\nما اغنى واحكم افكارك\nمين يقدر يكشف اسرارك\nفيض النعمة من انهارك\nيروي النفس العطشانة\n\nق) وحدك انت اللي بتستاهل \nاعيشلك عمري وزماني\nوحدك انت اللي بتستاهل\nياللي دمك غطاني\n\n3- لو تركوني امي وبيي\nوكل الناس اللي حواليَّ\nبتحضني وتحن عليَّ\nوبتمسح دمعات عيوني\n\nبوقت الشدة بتنجيني\nووقت الوحدة بتواسيني\nبلحظة ضعفي بتقويني\nوبتعزيني في احزاني\n\nق) وحدك انت اللي بتستاهل \nاعيشلك عمري وزماني\nوحدك انت اللي بتستاهل\nياللي دمك غطاني"}, {"id": "pp069", "cat": "pp", "title": "حبيتني وانا ماتحبش", "text": "ق) حبتني وانا ماتحبش\nوقبلت انك تلقاني \nواتغير حالي وقلبي \nوبقيت سكني وعنواني\n\n1- بالنعمة انا متخلص\nبمحبة كبيرة قوية\nولشخصك انا متخصص\u000bتعمل ما بدالك بيَّ\n\nق) حبتني وانا ماتحبش\nوقبلت انك تلقاني \nواتغير حالي وقلبي \nوبقيت سكني وعنواني\n\n2- في العالم كنت انا عايش\nمتاخد في دوامة\nوأما احب اني اصرخ\nابليس حاطط كمامة\n\nق) حبتني وانا ماتحبش\nوقبلت انك تلقاني \nواتغير حالي وقلبي \nوبقيت سكني وعنواني\n\n3- قُلت لك ابعد عني\nوطريقه مش عاوز امشيه\nلاقيتك جيت وناديتني\nوصليبك ضماني فيه\n\nق) حبتني وانا ماتحبش\nوقبلت انك تلقاني \nواتغير حالي وقلبي \nوبقيت سكني وعنواني\n\n4- بعد ما غيرت لي قلبي\nاشهد لك انك ربي\nقلبك طيب وبيسامح\nمهما ان كان كبير ذنبي\n\nق) حبتني وانا ماتحبش\nوقبلت انك تلقاني \nواتغير حالي وقلبي \nوبقيت سكني وعنواني"}, {"id": "pp070", "cat": "pp", "title": "حمامة طارت", "text": "ق) حمامة طارت\nفي الجو احتارت\nرجعت وقالت\nالعذراء بانت\n\n1- ريحة البخور\nفي السماء فاحت\nوصورة مريم\nفي السماء بانت\n\nق) حمامة طارت\nفي الجو احتارت\nرجعت وقالت\nالعذراء بانت\n\n2- زيتون وقبة\nوصليب ومنارة\nظهرت بجوارهم\nفخر العذارى\n\nق) حمامة طارت\nفي الجو احتارت\nرجعت وقالت\nالعذراء بانت\n\n3- ظهرتي يا مريم\nمين كان يفكر ؟\nإن في بلدنا\nالعذراء تظهر\n\nق) حمامة طارت\nفي الجو احتارت\nرجعت وقالت\nالعذراء بانت\n\n4- امرك يا ربي \nعجيب وعالي\nبسؤلات مريم\nاقبل سؤالي\n\nق) حمامة طارت\nفي الجو احتارت\nرجعت وقالت\nالعذراء بانت\n\n5- ده ظهورك لينا\nفرح قلوبنا\nوالرب فادينا\nبارك حياتنا\n\nق) حمامة طارت\nفي الجو احتارت\nرجعت وقالت\nالعذراء بانت\n\n6- ستي يا عذراء\nيا بتول يا طاهرة\nاذكري ابنك\nامام رب القدرة\n\nق) حمامة طارت\nفي الجو احتارت\nرجعت وقالت\nالعذراء بانت\n\n7- احنا اولادك\nاذكري ضعفي\nبصلاتك لينا\nيقوي ايمانا\n\nق) حمامة طارت\nفي الجو احتارت\nرجعت وقالت\nالعذراء بانت"}, {"id": "pp071", "cat": "pp", "title": "حيث قادني اسير", "text": "1- (حيث قادني أسير)3\n\nأمشي معه دوماً كل حين\n\n2- (ولو قادني للصلب)3\n\nأمشي معه دوماً كل حين\n\n3- (ولو إلى جثيماني)3\n\nأمشي معه دوماً كل حين\n\n4- (إن في حرب أم سلام)3\n\nأمشي معه دوماً كل حين\n\n5- (في صحة أم سقام)3\n\nأمشي معه دوماً كل حين\n\n6- (لو ضُرِبْتُ أو أُهِنْتُ)3\n\nأمشي معه دوماً كل حين\n\n7- (لو سُجِنْتُ أو رُجِمْتُ)3\n\nأمشي معه دوماً كل حين\n\n8- (سيقودني للظفر)3\n\nأمشي معه دوماً كل حين\n\n9- (ويأخذني للمجد)3\n\nأمشي معه دوماً كل حين\n\n10- (ربي اجذبني وراك)3\n\nأمشي معه دوماً كل حين"}, {"id": "pp072", "cat": "pp", "title": "خدنا على جبل عالي", "text": "ق) خدنا على جبل عالي\nهنينا بجلسة معاك\nكل النفوس هاتفرح\nوتهلل برؤياك\n\n1- ادينا كلام من عندك\nواملأنا تعزيات\nده كلامك هو المُحيي\nالمشبع باللذات\n\nق) خدنا على جبل عالي\nهنينا بجلسة معاك\nكل النفوس هاتفرح\nوتهلل برؤياك\n\n2- انت اللي بتعرف وحدك\nجميع الاحتياجات\nعايزينك انت بيدك\nتوزع الهيبات\n\nق) خدنا على جبل عالي\nهنينا بجلسة معاك\nكل النفوس هاتفرح\nوتهلل برؤياك\n\n3- افتح يدك واعطينا\nواغمرنا بالبركات\nده انت في العطا سخي\nولا عندك تعييرات\n\nق) خدنا على جبل عالي\nهنينا بجلسة معاك\nكل النفوس هاتفرح\nوتهلل برؤياك\n\n4- واملانا بسلامك\nوجهنا للصلوات\nعزينا يا رب بصوتك\nده كله مشتهيات\n\nق) خدنا على جبل عالي\nهنينا بجلسة معاك\nكل النفوس هاتفرح\nوتهلل برؤياك"}, {"id": "pp073", "cat": "pp", "title": "خلي ايامي افراح", "text": "ق) خلي ايامي افراح وهنا\nوالارض صارت لي سما\nوسط البرية عيشة هنية\nهي النعيم\n\n1- بعد سجودي لعرش الغرور\nثم انحنائي لذل الشرور\nيسوع نجاني حُبه اشتراني\nبدم كريم\n\nق) خلي ايامي افراح وهنا\nوالارض صارت لي سما\nوسط البرية عيشة هنية\nهي النعيم\n\n2- يسوع حاملني على اليدين\nويدللني على الركبتين\nسر عزائي فرحي وهنايا\nفي النعمة مُقيم\n\nق) خلي ايامي افراح وهنا\nوالارض صارت لي سما\nوسط البرية عيشة هنية\nهي النعيم\n\n3- كم ذُقت في بُعدي آلام\nوعشت يشتهي قلبي السلام\nوسط احزاني ذلي وهواني\nزارني الرحيم\n\nق) خلي ايامي افراح وهنا\nوالارض صارت لي سما\nوسط البرية عيشة هنية\nهي النعيم\n\n4- غربتي طالت وكان الحنين\nيملأ قلب يسوع الأمين\nفرح برجوعي ومسح لي دموعي\nوالفرح أقيم\n\nق) خلي ايامي افراح وهنا\nوالارض صارت لي سما\nوسط البرية عيشة هنية\nهي النعيم\n\n5- رفعني من وسط العبيد\nجلَّسني بحب شديد\nعلى الكراسي ورفع راسي\nحُبه عظيم\n\nق) خلي ايامي افراح وهنا\nوالارض صارت لي سما\nوسط البرية عيشة هنية\nهي النعيم\n\n6- من غير هموم كل الايام\nودربي نور بعد الظلام\nسائر امامي رئيس سلام\nصديق حميم\n\nق) خلي ايامي افراح وهنا\nوالارض صارت لي سما\nوسط البرية عيشة هنية\nهي النعيم\n\n7- لم يعاتبني على الخطية\nألبسني حُلة بيضة نقية\nخاتم في ايدي هنايا سعدي\nراح الأنين\n\nق) خلي ايامي افراح وهنا\nوالارض صارت لي سما\nوسط البرية عيشة هنية\nهي النعيم"}, {"id": "pp074", "cat": "pp", "title": "خليك معي", "text": "ق) خليك معي\nدي البرية صعبة عليَّ\nخليك معي\n\nخليك معي \nانا مقدرش اسير فيها لوحدي\nخليك معي\n\n1- ربي انت عارف. عالم وشايف. حولي مخاوف. فكن بجنبي. اسرع طمني. لاشي الخوف مني. فأنت عوني يا إلهي. لا تبعد عني\n\nق) خليك معي\nدي البرية صعبة عليَّ\nخليك معي\n\nخليك معي \nانا مقدرش اسير فيها لوحدي\nخليك معي\n\n2- متاعب وآلام. مصاعب وسهام. من عدو لا ينام. بيها بيحاربني. ربي تجيني. وأعطيني نعمة يا إلهي. فأنت معيني \n\nق) خليك معي\nدي البرية صعبة عليَّ\nخليك معي\n\nخليك معي \nانا مقدرش اسير فيها لوحدي\nخليك معي\n\n3- يمكن هيكون. في طريقي سجون. واجتاز في آتون. فلا تتركني. بل كن رفيقي. عوني في طريقي. ولو الكل اتخلى عني. فأنت صديقي \n\nق) خليك معي\nدي البرية صعبة عليَّ\nخليك معي\n\nخليك معي \nانا مقدرش اسير فيها لوحدي\nخليك معي"}, {"id": "pp075", "cat": "pp", "title": "دموعي في المخادع", "text": "1- دموعي في المخادع\nلها عندك تقدير\nوحدك لآهاتي سامع\nوفي يدك التدبير\n\nق) ولأنك أعظم أب\nحاسس بكل ما فيَّ\nوبتتعامل بالحب\nمع أي جروح مخفيَّة\n\n2- قلبي قاصدك وصارت\nاتدخل يا قدير\nسهل عدي الموانع\nشيل عني أي نير\n\nق) ولأنك أعظم أب\nحاسس بكل ما فيَّ\nوبتتعامل بالحب\nمع أي جروح مخفيَّة\n\n3- عارف انك في صفي \nضد قوى الشرير\nتعالج بالنعمة ضعفي\nتحلي حلقي المرير\n\nق) ولأنك أعظم أب\nحاسس بكل ما فيَّ\nوبتتعامل بالحب\nمع أي جروح مخفيَّة\n\n4- تعبت خلاص وراجع\nأنا لحضنك الكبير\nاشفيني من المواجع\nواصنع فيَّ التغيير\n\nق) ولأنك أعظم أب\nحاسس بكل ما فيَّ\nوبتتعامل بالحب\nمع أي جروح مخفيَّة"}, {"id": "pp076", "cat": "pp", "title": "ده اسمك مسكر", "text": "القرار\n ده اسمك مسكر معطر يا عذراء\nومجدك منور ما بين الغيوم\nونورك بيظهر ويجلب مسرة\nوفرحة وبشرى تغطي الغيوم\n\n1- معينة وحنونة والله ابونا\nيسمع تملي شفاعة الحنون\nبيعطف علينا ويبعت معونة\nشفاعتك تخلي همومنا تزول\n\nق) ده اسمك مسكر معطر يا عذراء\nومجدك منور ما بين الغيوم\nونورك بيظهر ويجلب مسرة\nوفرحة وبشرى تغطي الغيوم\n\n2- رضيعك يسوعك بيقبل صلاتك\nده ابنك الهك ورب الحياة\nيا ام المسيا يا عذراء نقية\nخدينا بشفاعتك لبر الامان\n\nق) ده اسمك مسكر معطر يا عذراء\nومجدك منور ما بين الغيوم\nونورك بيظهر ويجلب مسرة\nوفرحة وبشرى تغطي الغيوم\n\n3- يسوع مد ايده وفرح عبيده\nوجفف دموعنا عاملنا بحنان\nومنك تجسد وغني بنشيده\nصفوف الملائكة في ملئ الزمان\n\nق) ده اسمك مسكر معطر يا عذراء\nومجدك منور ما بين الغيوم\nونورك بيظهر ويجلب مسرة\nوفرحة وبشرى تغطي الغيوم\n\n4- مدينة حصينة بأسوار متينة\nسكن جوة منها إله الوجود\nده عمانوئيل معانا وفينا\nومنك أتانا يوفي الوعود\n\nق) ده اسمك مسكر معطر يا عذراء\nومجدك منور ما بين الغيوم\nونورك بيظهر ويجلب مسرة\nوفرحة وبشرى تغطي الغيوم"}, {"id": "pp077", "cat": "pp", "title": "ده لسانه حلو", "text": "1- ده لسانه حلو\nمعزي حلو\nأحلى من العسل\nوكله حلو\n\nق) حبيبي حلو\nوذقته حلو\nحلقه حلاوة\nوكله حلو\n\n2- ده طبعه حلو\nحنين وحلو\nينسى الآسية\nوكله حلو\n\nق) حبيبي حلو\nوذقته حلو\nحلقه حلاوة\nوكله حلو\n\n3- ده وعده حلو\nامين وحلو\nيسند ويفرح\nوكله حلو\n\nق) حبيبي حلو\nوذقته حلو\nحلقه حلاوة\nوكله حلو\n\n4- ده معطي حلو\nوسخي حلو\nيغني ويشبع\nوكله حلو\n\nق) حبيبي حلو\nوذقته حلو\nحلقه حلاوة\nوكله حلو\n\n5- في العشرة حلو\nطيب وحلو\nيشفي أمراضنا\nوكله حلو\n\nق) حبيبي حلو\nوذقته حلو\nحلقه حلاوة\nوكله حلو\n\n6- ده بيته حلو\nبركة وحلو\nوهناك احلى\nوكله حلو\n\nق) حبيبي حلو\nوذقته حلو\nحلقه حلاوة\nوكله حلو\n\n7- حبيبي حلو\nخليلي حلو\nشايل الشيلة عني\nوكله حلو\n\nق) حبيبي حلو\nوذقته حلو\nحلقه حلاوة\nوكله حلو\n\n8- تمجيده حلو\nتسبيحه حلو\nيفرح قلبي\nوكله حلو\n\nق) حبيبي حلو\nوذقته حلو\nحلقه حلاوة\nوكله حلو"}, {"id": "pp078", "cat": "pp", "title": "ربي اجذبني", "text": "1- ربي اجذبني\nوراك فأجري\nقدّس حياتي حياتي\nقلبي وفكري\n\n2- ادخلني الملك\nإلى حجاله\nفسر قلبي قلبي\nإذ رأى جماله\n\n3- قد كنت سودة\nكخيام قيدار\nألبسني ربي ربي\nكل الانوار\n\n4- انا جميلة\nمع كوني سودة\nيسوع ربي ربي\nهو جمالي\n\n5- شمس التجارب\nقد لوحتني\nلكن يسوع يسوع\nابداً ما تركني\n\n6- قد تركتني\nكل البَريّة\nوبنوا امي امي\nغضبوا عليَّ\n\n7- لمَّا رآنا\nفي الدنيا حزانى\nفتش علينا علينا\nمات واحيانا\n\n8- يسوع بقربي \nيسوع في قلبي\nيالسروري سروري\nبيسوع ربي"}, {"id": "pp079", "cat": "pp", "title": "ربي امنحني حُبَّك", "text": "1- المحبة تتأنى\nوكمان هي ترفق\nالمحبة لا تحسد\nبل هي دايماً تشفق\n\nق) ربي امنحني حبك\nربي اعطيني قلبك\nامنحني حبك يا رب\nارويني من نبع الحب\n\n2- المحبة لا تحسد\nبل تطلب للناس الخير\nالمحبة لا تحقد\nبل تشفق دايماً على الغير\n\nق) ربي امنحني حبك\nربي اعطيني قلبك\nامنحني حبك يا رب\nارويني من نبع الحب\n\n3- المحبة تحتمل\nوتصبر على كل شئ\nوهي لا تظن السوء\nبل تصدق كل شئ\n\nق) ربي امنحني حبك\nربي اعطيني قلبك\nامنحني حبك يا رب\nارويني من نبع الحب\n\n4- لا تكُن محبتنا\nبالكلام ولا باللسان\nبل تكُن محبتنا\nبالعمل والحق كمان\n\nق) ربي امنحني حبك\nربي اعطيني قلبك\nامنحني حبك يا رب\nارويني من نبع الحب\n\n5- نحن نعلم اننا\nحقاً قد انتقلنا\nمن الموت إلى الحياة\nعلشان بنحب الأخوة\n\nق) ربي امنحني حبك\nربي اعطيني قلبك\nامنحني حبك يا رب\nارويني من نبع الحب\n\n6- بهذا يعرف الناس\nاننا تلاميذ الرب\nإن كان لنا نحن أن نحب\nبعضنا بعضاً من القلب\n\nق) ربي امنحني حبك\nربي اعطيني قلبك\nامنحني حبك يا رب\nارويني من نبع الحب"}, {"id": "pp080", "cat": "pp", "title": "ربي بالروح املاني", "text": "1- ربي بالروح املاني\nواملأ كل الاواني\nواديني فرصة اكرمك\nقبل ما تيجي تاني\n\n2- ربي كل الاماني\nانك انت تتبناني\nواديني فرصة اخدمك\nقبل ما تخلص ايامي\n\n3- ربي ده عالم فاني\nبتوه فيه المعاني\nاديني فرصة اخدمك\nباللحن الحلو الروحاني\n\n4- ربي يسوع فداني\nساب كل سماه واتاني\nاديني فرصة من تاني\nده انت سيدي اللي فداني\n\n5- ربي موتك احياني\nسمرت يدك علشاني\nاديني فرصة اشكرك\nواعلي مجدك بإيماني\n\n6- ربي يسوع نجاني\nهداني بحبه ورواني\nاديني فرصة اعبدك\nبقلبي وفكري وكياني"}, {"id": "pp081", "cat": "pp", "title": "رغم الألف من الجموع", "text": "1- رغم الألف من الجموع\nلن ترضى تصرفهم بالجوع\nفمد ايديك اشبع عبيدك\nوها نحن منتظرينك\n\n2- رغم في قبره بقاله ايام\nقُلت لعازر حالاً قام\nفمد ايدك وإحيي عبيدك\nوها نحن منتظرينك\n\n3- برص وعمى ونزف دماء\nكل اللي لمسوه نالوا شفاء\nفمد ايدك وإشفي عبيدك\nوها نحن منتظرينك\n\n4- من بعد الخوف الكل ارتاح\nلمَّا انتهرت انت الرياح\nفمد ايدك طمن عبيدك\nوها نحن منتظرينك"}, {"id": "pp082", "cat": "pp", "title": "سامحنا يا فادينا", "text": "1- انت إلهنا الحي\nانت اللي قريب جاي \nهاتيجي وتعزينا\nوتمسح الدموع\n\nق) سامحنا يا فادينا\nباركنا يا يسوع\nعيونا بتترجاك\nمليانة بالدموع\n\n2- دايماً نتعدى عليك\nوالعالم بيغرينا\nقوينا قوينا\nمن فضلك يا يسوع\n\nق) سامحنا يا فادينا\nباركنا يا يسوع\nعيونا بتترجاك\nمليانة بالدموع\n\n3- تغاضى عن خطايانا\nعظّم لطفك ويانا\nوضع يدك علينا\nوبارك الجموع\n\nق) سامحنا يا فادينا\nباركنا يا يسوع\nعيونا بتترجاك\nمليانة بالدموع\n\n4- نوصيك بعمل يديك\nخدامك والسامعين\nخطاة ومؤمنين\nاوردهم للينبوع\n\nق) سامحنا يا فادينا\nباركنا يا يسوع\nعيونا بتترجاك\nمليانة بالدموع\n\n5- ولا حاجة نستاهلها \nمن اللي بتديهالنا\nدي محبتك غمرتنا\nنسجد لك في خشوع\n\nق) سامحنا يا فادينا\nباركنا يا يسوع\nعيونا بتترجاك\nمليانة بالدموع\n\n6- على القلوب بتقرع\nوطوبى للي يسمع\nويتوب توبة من قلبه\nتوبة من غير رجوع\n\nق) سامحنا يا فادينا\nباركنا يا يسوع\nعيونا بتترجاك\nمليانة بالدموع"}, {"id": "pp083", "cat": "pp", "title": "سامحني يا سيدي", "text": "ق) (سامحني) 3 واصفح عني\nلا ترذلني لا تتركني لا ترفضني يارب ارحمني\n(سامحني يا سيدي)3\n\n1- سامحني على الضعفات\nعلى السهوات وعلى اللذات\nسامحني على اللي فات\nربي لأجل الدم سامحني\n(سامحني يا سيدي)3\n\nق) (سامحني) 3 واصفح عني\nلا ترذلني لا تتركني لا ترفضني يارب ارحمني\n(سامحني يا سيدي)3\n\n2- سامحني على التفكير\nفي اي امر شرير\nسامحني على التقصير\nفي العمل والخدمة يا ربي\n(سامحني يا سيدي)3\n\nق) (سامحني) 3 واصفح عني\nلا ترذلني لا تتركني لا ترفضني يارب ارحمني\n(سامحني يا سيدي)3\n\n3- سامحني على الرجوع\nلحالة الجفاف والجوع\nسامحني يا يسوع \nعلى ضعفي واصفح عني\n(سامحني يا سيدي)3\n\nق) (سامحني) 3 واصفح عني\nلا ترذلني لا تتركني لا ترفضني يارب ارحمني\n(سامحني يا سيدي)3\n\n4- انت تعلم اني بشر\nوحولي قد انتشر\nالفساد وكل الشر\nربي انظر لي وأعني\n(سامحني يا سيدي)3\n\nق) (سامحني) 3 واصفح عني\nلا ترذلني لا تتركني لا ترفضني يارب ارحمني\n(سامحني يا سيدي)3\n\n5- ندمت ربي وبكيت\nصرخت من قلبي نديت\nقُلت خلاص عزمت نويت\nاعيشلك من كل قلبي\n(سامحني يا سيدي)3\n\nق) (سامحني) 3 واصفح عني\nلا ترذلني لا تتركني لا ترفضني يارب ارحمني\n(سامحني يا سيدي)3"}, {"id": "pp084", "cat": "pp", "title": "سايبين الدنيا", "text": "1- سايبين الدنيا بأتعابها\nسايبينها بمالها وبترابها\nلا احنا منها ولا اصحابها\nهايجينا يوم ونسيبها\n\nق) يا وطنا يا غالي علينا\nده الصبر اشتاق في عنينا\nامتى يا يسوع هاتجينا\nيا سمانا يا احلى ما لينا\n\n2- سايبين الدنيا بأعيادها\nلا تفرح قلب ولا بإيدها\nنفرح ويا اللي فدانا\nوالحزن هناك ينسانا\n\nق) يا وطنا يا غالي علينا\nده الصبر اشتاق في عنينا\nامتى يا يسوع هاتجينا\nيا سمانا يا احلى ما لينا\n\n3- المركب اهي معديانا\nوالموجة ان عليت شايلانا\nالفرحة دي مش سيعانا\nوعريسنا بيستنانا\n\nق) يا وطنا يا غالي علينا\nده الصبر اشتاق في عنينا\nامتى يا يسوع هاتجينا\nيا سمانا يا احلى ما لينا\n\n4- في السماء هنرنم فرحانين\nوعلى القيثارات كلنا عازفين\nوعلى العرش في وسطينا\nرب الارباب وفادينا\n\nق) يا وطنا يا غالي علينا\nده الصبر اشتاق في عنينا\nامتى يا يسوع هاتجينا\nيا سمانا يا احلى ما لينا"}, {"id": "pp085", "cat": "pp", "title": "سلم في الظروف", "text": "1- سلم في الظروف سلم في التجارب\nالمسيح الفادي صانع العجائب\nهو عن يمينك هو عن يسارك\nبيحارب حروبك ويبدد آلامك\n\n2- ليه تذهب للغير وانت ابن الفادي؟\nوعد ينجيك من يد الاعادي\nهو يسوع حبيبك ربك وإلهك\nيعطي المريض قوة ويجدد شبابك\n\n3- ادخل للمخادع واذرف الدموع\nواشكي له آلامك واحكي له ظروفك\nلا يتخلى عنك ولو زادت عيوبك\nفي دم الصليب يضمد جروحك\n\n4- في الظروف الصعبة ادخل يا ربي\nوفي وسط ضيقاتي الاقيك بجانبي\nبيدك تحميني وبصوتك تناديني\nتبدد ظلامي وفي لحظة تنجيني"}, {"id": "pp086", "cat": "pp", "title": "سمعت ترتيلة", "text": "1- سمعت ترتيلة جيش القديسين\nيرن بصوت عظيم\nفأبتهجت نفسي وقُلت امين\nكأني في دار النعيم\n\nق) كأني في دار النعيم\nمغسول بالدم الكريم\nجزت نهر الاردن دخلت كنعان\nكأني في دار النعيم\n\n2- ترى بعض الناس لا يدرى لماذا\nنحن في مجد عظيم \nجزنا نهر الاردن دخلنا كنعان\nكأنا في دار النعيم\n\nق) كأني في دار النعيم\nمغسول بالدم الكريم\nجزت نهر الاردن دخلت كنعان\nكأني في دار النعيم\n\n3- ما احلى أن نعبد الرب الامين\nنغني للفادي الكريم\nنمتلئ بالروح نشدو فرحين\nكأنا في دار النعيم\n\nق) كأني في دار النعيم\nمغسول بالدم الكريم\nجزت نهر الاردن دخلت كنعان\nكأني في دار النعيم\n\n4- نحن في إنتظار فادينا العجيب\nيأتي بهتاف عظيم\nفي سحب المجد نلاقي الحبيب\nوهذا لي كل النعيم\n\nق) كأني في دار النعيم\nمغسول بالدم الكريم\nجزت نهر الاردن دخلت كنعان\nكأني في دار النعيم"}, {"id": "pp087", "cat": "pp", "title": "شوفوا الخطية", "text": "1- شوفوا الخطية من شر لشر\nواللي يطاوعها ضروري ينضر\nاوعى يا مؤمن اوعاك تتغر وعقلني\n\nق) بعد الجنون عقلني\nبعد الجنون لبسني\nبعد الجنون جلسني\nبعد الجنون ورثني\n\n2- شوفوا الخطية المؤذية عايزة تحرمني من العطية\nلكن يسوع حنّ عليَّ\nوعقلني\n\nق) بعد الجنون عقلني\nبعد الجنون لبسني\nبعد الجنون جلسني\nبعد الجنون ورثني\n\n3- شوفوا الخطية اللي جرحتني\nوسط القبور وطرحتني\nلكن يسوع لن يتركني \nوعقلني\n\nق) بعد الجنون عقلني\nبعد الجنون لبسني\nبعد الجنون جلسني\nبعد الجنون ورثني\n\n4- لما رآني وانا حيران\nوكنت ساير مع الشيطان\nجاني يسوع وإداني الغفران\nوعقلني\n\nق) بعد الجنون عقلني\nبعد الجنون لبسني\nبعد الجنون جلسني\nبعد الجنون ورثني\n\n5- لما رآني وانا حزين\nوالدمع سايل من العينين\nقال لي تعالى هتروح لمين\nوعقلني\n\nق) بعد الجنون عقلني\nبعد الجنون لبسني\nبعد الجنون جلسني\nبعد الجنون ورثني"}, {"id": "pp088", "cat": "pp", "title": "شوفوا العالم", "text": "1- شوفوا العالم كله آلام\n(وانا في سلام)2\n(من يوم ما شُفتك)2\nوانا فرحان\n\nق) انا فرحان بحبيبي فرحان\n(عايش في امان)2\n(ياريت عرفتك)2\nوانا فرحان\n\n2- جوع وزلازل في البلدان\nوانا شبعان بيسوعي شبعان\n(من يوم ما جيتلك)2\nوانا فرحان\n\nق) انا فرحان بحبيبي فرحان\n(عايش في امان)2\n(ياريت عرفتك)2\nوانا فرحان\n\n3- امتى هاتيجي تعالى قوام\n(راكب الغمام)2\n(ساعتها اطيرلك)2\nوانا فرحان\n\nق) انا فرحان بحبيبي فرحان\n(عايش في امان)2\n(ياريت عرفتك)2\nوانا فرحان"}, {"id": "pp089", "cat": "pp", "title": "صوت آتٍ إليَّ", "text": "ق) صوت آتِ لي من السماء\nصوت الحب من ارض البهاء\nافرح يا ابني\nوافتح قلبك للعزاء\n\n1- للأبد ها قد احببتك\nعلى كفي نقشتك\nارفع وجهك\nبالنعمة خلصتك\n\nق) صوت آتِ لي من السماء\nصوت الحب من ارض البهاء\nافرح يا ابني\nوافتح قلبك للعزاء\n\n2- هل تنسى الأم رضيعها؟\nفلا ترحم ابن بطنها\nحتى هؤلاء تنسين\nأمَّا أنا لا أنساك\n\nق) صوت آتِ لي من السماء\nصوت الحب من ارض البهاء\nافرح يا ابني\nوافتح قلبك للعزاء\n\n3- القي عليَّ كل الهموم\nوانتظر نوري خلف الغيوم\nانت ابني \nلن اتركك للهموم\n\nق) صوت آتِ لي من السماء\nصوت الحب من ارض البهاء\nافرح يا ابني\nوافتح قلبك للعزاء"}, {"id": "pp090", "cat": "pp", "title": "صوت حبيبي", "text": "ق) صوت حبيبي فوق الجبال\nوهذا آتِ على التلال\nمتخطياً جبال الجلجثة\nعابراً تلال الناموس والآثام\n\n1- حبيبتي هيا رجوعاً إليَّ\nهوذا الشتاء مرَّ وزال\nكفاكِ شروداً في درب الخطية\nعيشي ربيعي هيا تعالِ\n\nق) صوت حبيبي فوق الجبال\nوهذا آتِ على التلال\nمتخطياً جبال الجلجثة\nعابراً تلال الناموس والآثام\n\n2- أسْمِعِني صوتك أريني وجهك\nولا تخجلي من كثرة الاثام\nفصوتك لطيف ووجهك جميل\nولحن الرجوع اجمل الالحان\n\nق) صوت حبيبي فوق الجبال\nوهذا آتِ على التلال\nمتخطياً جبال الجلجثة\nعابراً تلال الناموس والآثام\n\n3- انا سوداء بفعل الخطية\nواصل جمالي جمال الحبيب\nوبنو امي غضبوا عليَّ\nوجاء اضطهادي من باب القريب\n\nق) صوت حبيبي فوق الجبال\nوهذا آتِ على التلال\nمتخطياً جبال الجلجثة\nعابراً تلال الناموس والآثام\n\n4- كلك جميلاً بلا عيب فيكي\nقد نسيت قلبي ما احسن حُبك\nفي دمي اراكي بغير ظلمة فيكِ\nافتحي يا اختي يا حمامتي\n\nق) صوت حبيبي فوق الجبال\nوهذا آتِ على التلال\nمتخطياً جبال الجلجثة\nعابراً تلال الناموس والآثام\n\n5- مشرقة كالصبح طاهرة كالشمس\nتعلن الإنجيل فيهرب الظلام\nجميلة كالقمر مرهبة كالجيش\nاثبتي في حُبي تحملي الآلام\n\nق) صوت حبيبي فوق الجبال\nوهذا آتِ على التلال\nمتخطياً جبال الجلجثة\nعابراً تلال الناموس والآثام\n\n6- هذا حبيبي يسوع خليلي\nابيض رقيق بطُهر الإله\nتحبه نفسي وصار دليلي\nواحمر كفادي طهرني بدماه\n\nق) صوت حبيبي فوق الجبال\nوهذا آتِ على التلال\nمتخطياً جبال الجلجثة\nعابراً تلال الناموس والآثام\n\n7- انا لحبيبي وحبيبي لي\nوتحت ظله اشتهيت الجلوس\nحلوة لحلقي ثمرته\nإنه يناديني يا اختي العروس\n\nق) صوت حبيبي فوق الجبال\nوهذا آتِ على التلال\nمتخطياً جبال الجلجثة\nعابراً تلال الناموس والآثام"}, {"id": "pp091", "cat": "pp", "title": "صوت يسوع جميل", "text": "1- يوم ما سمعت صوت حبيبي بينادي عليَّ\nصوته الحلو كان ممزوج بعطف وحنية\n\nنداني فداني وسدد كل الدين اللي عليَّ\nطهر قلبي وخلص نفسي وفتح لي عينيَّ\n\nق) صوت يسوع جميل\nيشفي كل عليل\nتشهد له السموات والارض\nوتشهد له الاناجيل\n\n2- لما فتح لي عينيَّ\nرأيت جمال عجيب\nشفت آثار الحربة في جنبه\nوجروح الصليب\n\nشفت النور والنعمة في وجهه\nلما نظرت إليه\nشفت الحب وشفت الشهد\nبيقطر من شفتيه\n\nق) صوت يسوع جميل\nيشفي كل عليل\nتشهد له السموات والارض\nوتشهد له الاناجيل\n\n3- صوته ينور قلب الاعمى\nيشفي كل عليل\nشاول يصبح بولس اعظم\nخادم للإنجيل\n\nفي الحال غير كل طريقه\nلما الرب نداه\nتعالى من بُعدك حالاً\nواسمع صوت الله\n\nق) صوت يسوع جميل\nيشفي كل عليل\nتشهد له السموات والارض\nوتشهد له الاناجيل\n\n4- صوته ينادي كل مؤمن\nلا تخشى الآلام\nده معينك في العالم ربك\nإله السلام\n\nلما تواجهك اي ضيقة\nاذكر انك غريب\nومسافر لديار حبيبك\nورحيلك غريب\n\nق) صوت يسوع جميل\nيشفي كل عليل\nتشهد له السموات والارض\nوتشهد له الاناجيل"}, {"id": "pp092", "cat": "pp", "title": "طريق يسوع", "text": "1- طريق يسوع فيها الخلاص\nبالرغم من كلام الناس\nوانا بيسوع مرفوع الراس\nواكليلي لامع في الابدية\n\nق) ياريتك تيجي الساعة دي\nتنسيني آلام البرية\nوإن قام العالم عليَّ\nأنا ليسوع ويسوع ليَّ\n\n2- كل العالم يجرحني\nلكن يسوع يفرحني\nوعلى الصليب سامحني\nواكليلي لماع في الابدية\n\nق) ياريتك تيجي الساعة دي\nتنسيني آلام البرية\nوإن قام العالم عليَّ\nأنا ليسوع ويسوع ليَّ\n\n3- كل العالم يبكيني\nلكن يسوع يعزيني\nوعلى السحاب يلاقيني\nوأكليلي لماع في الابدية\n\nق) ياريتك تيجي الساعة دي\nتنسيني آلام البرية\nوإن قام العالم عليَّ\nأنا ليسوع ويسوع ليَّ\n\n4- اترك يسوع واروح لمين\nوالعالم قاسي وكله آنين\nيسوع رجاي يا مؤمنين\nواكليلي لماع في الابدية\n\nق) ياريتك تيجي الساعة دي\nتنسيني آلام البرية\nوإن قام العالم عليَّ\nأنا ليسوع ويسوع ليَّ\n\n5- طريق يسوع فيها السرور\nبالرغم من كل الشرور\nوانا بيسوع عايش في النور\nواكليلي لماع في الابدية\n\nق) ياريتك تيجي الساعة دي\nتنسيني آلام البرية\nوإن قام العالم عليَّ\nأنا ليسوع ويسوع ليَّ\n\n6- يا يسوع رجاي ومناي\nبتشبعني عز وعناية\nياريت تيجيني وكفاية\nواكليلي لماع في الابدية\n\nق) ياريتك تيجي الساعة دي\nتنسيني آلام البرية\nوإن قام العالم عليَّ\nأنا ليسوع ويسوع ليَّ"}, {"id": "pp093", "cat": "pp", "title": "طوبى لأُناس", "text": "ق) طوبى لأُناس عزهم بك\nطرق بيتك في قلوبهم\nعابرين في وادي البكاء\nيصيرونه ينبوعاً لهم\n\n1- قلبي ولحمي هما يهتفان\nللرب الإله الحي الودود\nطوبى لمن يسكنون هناك\nيسبحونك حمداً وسجود\n\nق) طوبى لأُناس عزهم بك\nطرق بيتك في قلوبهم\nعابرين في وادي البكاء\nيصيرونه ينبوعاً لهم\n\n2- ما احلى مساكنك يا ربنا\nقوياً انت يا رب الجنود\nفقلبي دوماً في شوق إليك\nلذلك إليك نفسي تتوق\n\nق) طوبى لأُناس عزهم بك\nطرق بيتك في قلوبهم\nعابرين في وادي البكاء\nيصيرونه ينبوعاً لهم\n\n3- لأن اليوم في ديارك\nخيراً عندي من الف يوم\nفضَّلت الوقوف على اعتابك\nعلى أن أسكن مع خطاة القوم\n\nق) طوبى لأُناس عزهم بك\nطرق بيتك في قلوبهم\nعابرين في وادي البكاء\nيصيرونه ينبوعاً لهم\n\n4- لأن الرب شمس ومجن\nفهو يعطي رحمة وعون\nعن السالكين إليك بالكمال\nوعن طالبيه لا يمنع خير\n\nق) طوبى لأُناس عزهم بك\nطرق بيتك في قلوبهم\nعابرين في وادي البكاء\nيصيرونه ينبوعاً لهم"}, {"id": "pp094", "cat": "pp", "title": "عُد يا إلهي", "text": "ق) عُد يا إلهي واتطلع\nوانظر من السماء\nتعهد الكرمة\nبالخصب وبالنماء\n\n1- كنيستي أرجو لكِ\nمن عِزة الإله\nخلاص كل الشعب \nيا سفينة النجاة\n\nق) عُد يا إلهي واتطلع\nوانظر من السماء\nتعهد الكرمة\nبالخصب وبالنماء\n\n2- ليحفظ الرب لكِ عهداً\nعلى الدوام\nوليملأ الإله \nابراجك بالسلام\n\nق) عُد يا إلهي واتطلع\nوانظر من السماء\nتعهد الكرمة\nبالخصب وبالنماء\n\n3- اطلب راحة لك\nفي قصرك الرحب\nدوماً لأجل إخوتي\nوالأهل والصُحُبِ\n\nق) عُد يا إلهي واتطلع\nوانظر من السماء\nتعهد الكرمة\nبالخصب وبالنماء\n\n4- من أجل بيت الله\nاطلب لك الخيرات\nملتمساً فوزاً لك\nمن مصدر القوات\n\nق) عُد يا إلهي واتطلع\nوانظر من السماء\nتعهد الكرمة\nبالخصب وبالنماء\n\n5- انت إلهنا القوي\nالمُنجِد المُعين\nعونك ملجأ لنا\nوحصننا الحصين\n\nق) عُد يا إلهي واتطلع\nوانظر من السماء\nتعهد الكرمة\nبالخصب وبالنماء"}, {"id": "pp095", "cat": "pp", "title": "عروس منصورة", "text": "1- عروس منصورة\nوفي أجمل صورة\nومجدك يُرى\nعلى حبايبك 2\n\nق) اعلن حضورك\nواشرق بنورك\nفيض من سرورك\nعلى حبايبك 2\n\n2- سلاح مضمون\nيهدم حصون\nيهدم ظنون\nضد حبايبك 2\n\nق) اعلن حضورك\nواشرق بنورك\nفيض من سرورك\nعلى حبايبك 2\n\n3- عروس بهية\nطاهرة نقية\nجيش بألوية\nكل حبايبك 2\n\nق) اعلن حضورك\nواشرق بنورك\nفيض من سرورك\nعلى حبايبك 2\n\n4- رجالتك اية\nليهم حماية\nمن كل شكاية\nعلى حبايبك 2\n\nق) اعلن حضورك\nواشرق بنورك\nفيض من سرورك\nعلى حبايبك 2\n\n5- انت في وسطينا\nومكتر بينا\nووعدك زينة\nعلى حبايبك 2\n\nق) اعلن حضورك\nواشرق بنورك\nفيض من سرورك\nعلى حبايبك 2\n\n6- امشي قدامنا\nوبطون اقدامنا\nكل اللي تدوسه\nهايكون لحبايبك 2\n\nق) اعلن حضورك\nواشرق بنورك\nفيض من سرورك\nعلى حبايبك 2\n\n7- قلوب فرحانة\nوبشوق مليانة\nامتى هاتيجي\nتيجي لحبايبك 2\n\nق) اعلن حضورك\nواشرق بنورك\nفيض من سرورك\nعلى حبايبك 2"}]);
